INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH0' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN11_T1')), 'B0', 'BỘ GIÁO DỤC VÀ ĐÀO TẠO', 0, 1, $JSON$
{
  "content": [
    "# BỘ GIÁO DỤC VÀ ĐÀO TẠO",
    "",
    "# TOÁN 11",
    "## TẬP MỘT",
    "",
    "[Hình ảnh: Biểu đồ đường, toà nhà chọc trời, thành phố và mặt nước. Có các đường cong toán học, sóng, kí hiệu không gian. Khung cảnh có vẻ là cảnh quan đô thị hồ Tây hoặc một hồ nước ở thành phố với các kết nối mạng.]",
    "",
    "**GD**",
    "**NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM**",
    "HÀ HUY KHOÁI (Tổng Chủ biên)",
    "CUNG THẾ ANH – TRẦN VĂN TẤN – ĐẶNG HÙNG THẮNG (đồng Chủ biên)",
    "TRẦN MẠNH CƯỜNG – LÊ VĂN CƯỜNG – NGUYỄN ĐẠT ĐĂNG – LÊ VĂN HIỆN",
    "PHAN THANH HỒNG – TRẦN ĐÌNH KẾ – PHẠM ANH MINH – NGUYỄN THỊ KIM SƠN",
    "",
    "# TOÁN 11",
    "(Tái bản lần thứ ba)",
    "",
    "## TẬP MỘT",
    "",
    "**KẾT NỐI TRI THỨC VỚI CUỘC SỐNG**",
    "",
    "**NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM**",
    "# HƯỚNG DẪN SỬ DỤNG SÁCH",
    "",
    "1. Mỗi bài học đều được thiết kế theo cấu trúc gồm những phần sau đây.",
    "**Thuật ngữ:** Điểm tên các đối tượng chính của bài học.",
    "**Kiến thức, kĩ năng:** Giúp em xác định những nội dung kiến thức, kĩ năng chính cần lĩnh hội và rèn luyện trong bài học.",
    "**Mở đầu:** Đưa ra tình huống làm nảy sinh nhu cầu học tập; nó có thể là một bài toán thực tế đại diện, hay là một đoạn dẫn nhập. Em không cần trả lời ngay các câu hỏi hay yêu cầu được đặt ra ở phần này, mà sẽ giải quyết chúng trong bài học, sau khi đã lĩnh hội được lượng tri thức và kĩ năng cần thiết.",
    "**Mục kiến thức:** Sau phần mở đầu, bài học được chia thành các mục theo từng chủ đề. Nhìn chung, mỗi đơn vị kiến thức có cấu trúc sau đây:",
    "**Hình thành kiến thức:** Em cần tích cực tham gia vào các hoạt động (**HĐ**) để chiếm lĩnh tri thức. Các **HĐ** này cho em cơ hội quan sát và trải nghiệm, tính toán và lập luận để đi tới [khung kiến thức] một cách tự nhiên.",
    "**Ví dụ:** Em có thể học ở đây phương pháp, cách lập luận và tính toán, cách trình bày lời giải bài toán.",
    "**Luyện tập:** Vận dụng kiến thức đã học, tham khảo ví dụ tương ứng, em hãy luyện tập để củng cố kiến thức và rèn luyện kĩ năng.",
    "**Vận dụng:** Trên nền tảng kiến thức và kĩ năng đã được học, em giải quyết các bài toán gắn với thực tế, kết nối tri thức với các lĩnh vực khác nhau trong học tập, khoa học và cuộc sống.",
    "Em có thể bắt gặp một [khung chữ] nhằm hỗ trợ hoặc bình luận,... cho nội dung tương ứng được đề cập ở bên cạnh.",
    "Ngoài bốn thành phần cơ bản ở trên, trong một đơn vị kiến thức, em còn có thể có cơ hội tham gia vào **Khám phá, Trải nghiệm, Thảo luận**, trả lời [?], mở rộng hiểu biết cùng *Em có biết?,...*",
    "**Bài tập:** Em chủ động thực hiện ngoài giờ trên lớp, tuy vậy, thầy/cô sẽ dành thời lượng nhất định để cùng em điểm qua các bài tập này.",
    "2. Các bảng tra cứu và giải thích thuật ngữ (được đặt ở cuối sách) cung cấp địa chỉ tra cứu và giải thích một số khái niệm, công thức được phát biểu trong sách.",
    "",
    "---",
    "",
    "*Hãy bảo quản, giữ gìn sách giáo khoa*",
    "*để dành tặng các em học sinh lớp sau!*",
    "",
    "2",
    "# LỜI NÓI ĐẦU",
    "",
    "Các em học sinh yêu quý!",
    "",
    "Trên tay các em là cuốn *TOÁN 11* của bộ sách “Kết nối tri thức với cuộc sống”. Đúng như tên gọi của bộ sách, các kiến thức trình bày ở đây chủ yếu xuất phát từ những tình huống của cuộc sống quanh ta và trở lại giúp ta giải quyết những vấn đề của cuộc sống. Vì thế, khi học Toán theo cuốn sách này, các em sẽ cảm nhận được rằng, Toán học thật là gần gũi.",
    "",
    "Đoạn mở đầu của các chương, các bài học thường đưa ra những tình huống, những ví dụ thực tế cho thấy sự cần thiết phải đưa đến những khái niệm toán học mới. Qua đó, các em sẽ được trau dồi những kĩ năng cần thiết cho một công dân trong thời hiện đại, đó là khả năng “mô hình hoá”. Khi đã đưa vấn đề thực tiễn về bài toán (mô hình toán học), chúng ta sẽ phát hiện thêm những kiến thức toán học mới, để cùng với những kiến thức đã biết giải quyết bài toán thực tiễn đặt ra.",
    "",
    "Hi vọng rằng, qua mỗi bài học, mỗi chương sách, qua mỗi vòng lặp từ thực tiễn đến tri thức toán học, rồi từ tri thức toán học quay về thực tiễn, *TOÁN 11* sẽ giúp các em trưởng thành nhanh chóng và trở thành người bạn thân thiết của các em.",
    "",
    "Chúc các em thành công cùng *TOÁN 11*!",
    "",
    "3",
    "# MỤC LỤC",
    "",
    "| CHƯƠNG I. HÀM SỐ LƯỢNG GIÁC VÀ PHƯƠNG TRÌNH LƯỢNG GIÁC | |",
    "| :--- | :--- |",
    "| Bài 1. Giá trị lượng giác của góc lượng giác | 5 |",
    "| Bài 2. Công thức lượng giác | 17 |",
    "| Bài 3. Hàm số lượng giác | 22 |",
    "| Bài 4. Phương trình lượng giác cơ bản | 31 |",
    "| Bài tập cuối chương I | 40 |",
    "",
    "| CHƯƠNG II. DÃY SỐ. CẤP SỐ CỘNG VÀ CẤP SỐ NHÂN | |",
    "| :--- | :--- |",
    "| Bài 5. Dãy số | 42 |",
    "| Bài 6. Cấp số cộng | 48 |",
    "| Bài 7. Cấp số nhân | 52 |",
    "| Bài tập cuối chương II | 56 |",
    "",
    "| CHƯƠNG III. CÁC SỐ ĐẶC TRƯNG ĐO XU THẾ TRUNG TÂM CỦA MẪU SỐ LIỆU GHÉP NHÓM | |",
    "| :--- | :--- |",
