INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN11_T1')), 'B1', 'Giá trị lượng giác của góc lượng giác', 5, 1, $JSON$
{
  "content": [
    "# CHƯƠNG I",
    "# HÀM SỐ LƯỢNG GIÁC VÀ PHƯƠNG TRÌNH LƯỢNG GIÁC",
    "",
    "Chương này giới thiệu khái niệm góc lượng giác, giá trị lượng giác của góc lượng giác, các công thức lượng giác cơ bản, hàm số lượng giác, cách giải phương trình lượng giác cơ bản và một số ứng dụng của lượng giác trong thực tiễn.",
    "",
    "[Hình ảnh: Đồ thị hàm số sin/cos màu đỏ cắt trục hoành $t$, có các điểm đánh dấu trên trục $t$. Bên cạnh là hình ảnh cách điệu của một vòng xoay mặt trời (vòng đu quay khổng lồ) màu đỏ, có đánh dấu góc $t_0$ và điểm xuất phát. Cả hai biểu đồ và hình ảnh đều hiển thị liên quan đến một hàm lượng giác.]",
    "",
    "# Bài 1. GIÁ TRỊ LƯỢNG GIÁC CỦA GÓC LƯỢNG GIÁC",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Góc lượng giác<br>• Số đo của góc lượng giác<br>• Đường tròn lượng giác<br>• Giá trị lượng giác của góc lượng giác<br>• Hệ thức cơ bản giữa các giá trị lượng giác | • Nhận biết các khái niệm cơ bản về góc lượng giác.<br>• Nhận biết khái niệm giá trị lượng giác của một góc lượng giác.<br>• Mô tả bảng giá trị lượng giác của một số góc lượng giác thường gặp; hệ thức cơ bản giữa các giá trị lượng giác của một góc lượng giác; quan hệ giữa các giá trị lượng giác của các góc lượng giác có liên quan đặc biệt: bù nhau, phụ nhau, đối nhau, hơn kém nhau $\\pi$.<br>• Sử dụng máy tính cầm tay để tính giá trị lượng giác của một góc lượng giác khi biết số đo của góc đó.<br>• Giải quyết một số vấn đề thực tiễn gắn với giá trị lượng giác của góc lượng giác. |",
    "",
    "Trạm vũ trụ Quốc tế ISS (tên tiếng Anh: International Space Station) nằm trong quỹ đạo tròn cách bề mặt Trái Đất khoảng 400 km (H.1.1). Nếu trạm mặt đất theo dõi được trạm vũ trụ ISS khi nó nằm trong góc $45^{\\circ}$ ở tâm của quỹ đạo tròn này phía trên ăng-ten theo dõi, thì trạm vũ trụ ISS đã di chuyển được bao nhiêu kilômét trong khi nó đang được trạm mặt đất theo dõi? Giả sử rằng bán kính của Trái Đất là $6 400 \\text{ km}$. Làm tròn kết quả đến hàng đơn vị.",
    "",
    "[Hình ảnh: Trái Đất và quỹ đạo của trạm vũ trụ ISS. Hình vẽ minh họa khoảng cách 400 km từ bề mặt Trái Đất tới quỹ đạo, bán kính Trái Đất 6 400 km, và một góc $45^{\\circ}$ ở tâm quét một cung trên quỹ đạo.]",
    "*Hình 1.1*",
    "",
    "5",
    "## 1. GÓC LƯỢNG GIÁC",
    "",
    "### a) Khái niệm góc lượng giác và số đo của góc lượng giác",
    "**HĐ1. Nhận biết khái niệm góc lượng giác**",
    "Trên đồng hồ ở Hình 1.2, kim phút đang chỉ đúng số 2.",
    "a) Phải quay kim phút mấy phần của một vòng tròn theo chiều quay ngược chiều kim đồng hồ để nó chỉ đúng số 12?",
    "b) Phải quay kim phút mấy phần của một vòng tròn theo chiều quay của kim đồng hồ để nó chỉ đúng số 12?",
    "c) Có bao nhiêu cách quay kim phút theo một chiều xác định để kim phút từ vị trí chỉ đúng số 2 về vị trí chỉ đúng số 12?",
    "",
    "[Hình ảnh: Một mặt đồng hồ kim chỉ 12 giờ 10 phút. Kim dài chỉ số 2, kim ngắn chỉ qua số 12 một chút.]",
    "*12 giờ 10 phút*",
    "*Hình 1.2*",
    "",
    "Trong mặt phẳng, cho hai tia $Ou, Ov$. Xét tia $Om$ cùng nằm trong mặt phẳng này. Nếu tia $Om$ quay quanh điểm $O$, theo một chiều nhất định từ $Ou$ đến $Ov$, thì ta nói nó quét một **góc lượng giác** với tia đầu $Ou$, tia cuối $Ov$ và kí hiệu là $(Ou, Ov)$.",
    "",
    "Góc lượng giác $(Ou, Ov)$ chỉ được xác định khi ta biết được chuyển động quay của tia $Om$ từ tia đầu $Ou$ đến tia cuối $Ov$ (H.1.3). Ta quy ước: Chiều quay ngược với chiều quay của kim đồng hồ là *chiều dương*, chiều quay cùng chiều kim đồng hồ là *chiều âm*.",
    "",
    "[Hình ảnh: Hình 1.3 gồm 3 hình vẽ góc lượng giác. Hình 1 mô tả tia $Om$ quay từ $Ou$ đến $Ov$ theo chiều dương (+). Hình 2 mô tả tia $Om$ quay từ $Ou$ đến $Ov$ theo chiều âm (-). Hình 3 mô tả tia $Om$ quay từ $Ou$ đến $Ov$ (chiều dương).]",
    "*Hình 1.3*",
    "",
    "Khi đó, nếu tia $Om$ quay theo chiều dương đúng một vòng ta nói tia $Om$ quay góc $360^{\\circ}$, quay đúng 2 vòng ta nói nó quay góc $720^{\\circ}$; quay theo chiều âm nửa vòng ta nói nó quay góc $-180^{\\circ}$, quay theo chiều âm 1,5 vòng ta nói nó quay góc $-1,5 \\cdot 360^{\\circ} = -540^{\\circ}, \\dots$",
    "",
    "Khi tia $Om$ quay góc $\\alpha^{\\circ}$ thì ta nói góc lượng giác mà tia đó quét nên có số đo $\\alpha^{\\circ}$. **Số đo của góc lượng giác** có tia đầu $Ou$, tia cuối $Ov$ được kí hiệu là $\\text{sđ}(Ou, Ov)$.",
    "",
    "[Hình ảnh: 4 hình vẽ biểu diễn các góc lượng giác đặc biệt. Hình 1: sđ$(Ou, Ov) = 360^{\\circ}$ (quay một vòng chiều dương). Hình 2: sđ$(Ou, Ov) = 720^{\\circ}$ (quay hai vòng chiều dương). Hình 3: sđ$(Ou, Ov) = -180^{\\circ}$ (quay nửa vòng chiều âm). Hình 4: sđ$(Ou, Ov) = -540^{\\circ}$ (quay 1,5 vòng chiều âm).]",
    "",
    "Mỗi góc lượng giác gốc $O$ được xác định bởi tia đầu $Ou$, tia cuối $Ov$ và số đo của nó.",
    "",
    "**Chú ý.** Cho hai tia $Ou, Ov$ thì có vô số góc lượng giác tia đầu $Ou$, tia cuối $Ov$. Mỗi góc lượng giác như thế đều kí hiệu là $(Ou, Ov)$. Số đo của các góc lượng giác này sai khác nhau một bội nguyên của $360^{\\circ}$.",
    "",
    "6",
    "**Ví dụ 1.** Cho góc hình học $uOv$ có số đo $60^{\\circ}$ (H.1.4). Xác định số đo của các góc lượng giác $(Ou, Ov)$ và $(Ov, Ou)$.",
    "**Giải**",
    "Ta có:",
    "- Các góc lượng giác tia đầu $Ou$, tia cuối $Ov$ có số đo là",
    "$\\text{sđ}(Ou, Ov) = 60^{\\circ} + k360^{\\circ} \\, (k \\in \\mathbb{Z})$.",
    "- Các góc lượng giác tia đầu $Ov$, tia cuối $Ou$ có số đo là",
    "$\\text{sđ}(Ov, Ou) = -60^{\\circ} + k360^{\\circ} \\, (k \\in \\mathbb{Z})$.",
    "",
    "[Hình ảnh: Góc lượng giác $uOv$ bằng $60^{\\circ}$ theo chiều dương.]",
    "*Hình 1.4*",
    "",
    "**Luyện tập 1.** Cho góc hình học $\\widehat{uOv} = 45^{\\circ}$. Xác định số đo của góc lượng giác $(Ou, Ov)$ trong mỗi trường hợp sau:",
    "",
    "[Hình ảnh: a) Góc hình học $\\widehat{uOv} = 45^{\\circ}$ nhưng tia quay theo chiều âm với góc quay $\\alpha$ tạo ra bởi tia từ $Ou$ quay góc lớn. b) Góc hình học $\\widehat{uOv} = 45^{\\circ}$ tia $Ou$ quay theo chiều âm.]",
    "*(Lưu ý: Hình ảnh cho thấy góc quay khác nhau)*",
    "",
    "### b) Hệ thức Chasles",
    "**HĐ2. Nhận biết hệ thức Chasles**",
    "Cho ba tia $Ou, Ov, Ow$ với số đo của các góc hình học $uOv$ và $vOw$ lần lượt là $30^{\\circ}$ và $45^{\\circ}$.",
    "a) Xác định số đo của ba góc lượng giác $(Ou, Ov), (Ov, Ow)$ và $(Ou, Ow)$ được chỉ ra ở Hình 1.5.",
    "b) Với các góc lượng giác ở câu a, chứng tỏ rằng có một số nguyên $k$ để $\\text{sđ}(Ou, Ov) + \\text{sđ}(Ov, Ow) = \\text{sđ}(Ou, Ow) + k360^{\\circ}$.",
    "",
    "[Hình ảnh: Ba tia $Ou, Ov, Ow$ tạo thành góc $uOv = 30^{\\circ}$ và $vOw = 45^{\\circ}$.]",
    "*Hình 1.5*",
    "",
    "**Hệ thức Chasles:** Với ba tia $Ou, Ov, Ow$ bất kì, ta có",
    "$\\text{sđ}(Ou, Ov) + \\text{sđ}(Ov, Ow) = \\text{sđ}(Ou, Ow) + k360^{\\circ} \\, (k \\in \\mathbb{Z})$.",
    "",
    "**Nhận xét.** Từ hệ thức Chasles, ta suy ra:",
    "Với ba tia tuỳ ý $Ox, Ou, Ov$, ta có",
    "$\\text{sđ}(Ou, Ov) = \\text{sđ}(Ox, Ov) - \\text{sđ}(Ox, Ou) + k360^{\\circ} \\, (k \\in \\mathbb{Z})$.",
    "Hệ thức này đóng vai trò quan trọng trong việc tính toán số đo của góc lượng giác.",
    "",
    "[Khung chữ bên lề: Hệ thức này tương tự công thức $\\overrightarrow{AB} = \\overrightarrow{OB} - \\overrightarrow{OA}$. Hình ảnh chú rô-bốt nhỏ dễ thương.]",
    "",
    "**Ví dụ 2.** Cho một góc lượng giác $(Ox, Ou)$ có số đo $-270^{\\circ}$ và một góc lượng giác $(Ox, Ov)$ có số đo $135^{\\circ}$. Tính số đo của các góc lượng giác $(Ou, Ov)$.",
    "",
    "7",
    "**Giải**",
    "Số đo của các góc lượng giác tia đầu $Ou$, tia cuối $Ov$ là",
    "$\\text{sđ}(Ou, Ov) = \\text{sđ}(Ox, Ov) - \\text{sđ}(Ox, Ou) + k360^{\\circ}$",
    "$= 135^{\\circ} - (-270^{\\circ}) + k360^{\\circ} = 405^{\\circ} + k360^{\\circ}$",
    "$= 45^{\\circ} + (k + 1)360^{\\circ} = 45^{\\circ} + m360^{\\circ} \\, (m = k + 1, m \\in \\mathbb{Z})$.",
    "Vậy các góc lượng giác $(Ou, Ov)$ có số đo là $45^{\\circ} + m360^{\\circ} \\, (m \\in \\mathbb{Z})$.",
    "",
    "**Luyện tập 2.** Cho một góc lượng giác $(Ox, Ou)$ có số đo $240^{\\circ}$ và một góc lượng giác $(Ox, Ov)$ có số đo $-270^{\\circ}$. Tính số đo của các góc lượng giác $(Ou, Ov)$.",
    "",
    "## 2. ĐƠN VỊ ĐO GÓC VÀ ĐỘ DÀI CUNG TRÒN",
    "",
    "### a) Đơn vị đo góc và cung tròn",
    "",
    "**Đơn vị độ:** Để đo góc, ta dùng đơn vị độ. Ta đã biết: Góc $1^{\\circ}$ bằng $\\frac{1}{180}$ góc bẹt.",
    "Đơn vị độ được chia thành những đơn vị nhỏ hơn: $1^{\\circ} = 60'; 1' = 60\"$.",
    "",
    "Đối với các góc lượng giác, khi mà số vòng quay trong chuyển động tương ứng từ tia đầu đến tia cuối là khá lớn thì số đo của chúng tính bằng độ sẽ trở nên cồng kềnh. Do đó, trong khoa học và kĩ thuật, bên cạnh việc đo bằng độ, người ta còn sử dụng đơn vị đo góc bằng radian.",
    "",
    "**Đơn vị radian:** Cho đường tròn $(O)$ tâm $O$, bán kính $R$ và một cung $AB$ trên $(O)$ (H.1.6).",
    "",
    "Ta nói cung tròn $AB$ có số đo bằng 1 radian nếu độ dài của nó đúng bằng bán kính $R$.",
    "Khi đó ta cũng nói rằng góc $AOB$ có số đo bằng 1 radian và viết: $\\widehat{AOB} = 1 \\text{ rad}$.",
    "",
    "**Quan hệ giữa độ và radian:** Do đường tròn có độ dài là $2\\pi R$ nên nó có số đo $2\\pi \\text{ rad}$. Mặt khác, đường tròn có số đo bằng $360^{\\circ}$ nên ta có $360^{\\circ} = 2\\pi \\text{ rad}$.",
    "Do đó ta viết:",
    "$1^{\\circ} = \\frac{\\pi}{180} \\text{ rad} \\quad \\text{và} \\quad 1 \\text{ rad} = \\left(\\frac{180}{\\pi}\\right)^{\\circ}$.",
    "",
    "[Hình ảnh: Đường tròn tâm $O$, cung $AB$ có độ dài bằng bán kính $R$. Góc ở tâm $AOB$ được đánh dấu là $1 \\text{ rad}$.]",
    "*Hình 1.6*",
    "",
    "**Chú ý.** Khi viết số đo của một góc theo đơn vị radian, người ta thường không viết chữ rad sau số đo. Chẳng hạn góc $\\frac{\\pi}{2}$ được hiểu là góc $\\frac{\\pi}{2} \\text{ rad}$.",
    "",
    "8",
    "**Ví dụ 3**",
    "a) Đổi từ độ sang radian các số đo sau: $45^{\\circ}; 150^{\\circ}$.",
    "b) Đổi từ radian sang độ các số đo sau: $\\frac{\\pi}{3}; \\frac{5\\pi}{4}$.",
    "**Giải**",
    "a) Ta có:",
    "$45^{\\circ} = 45 \\cdot \\frac{\\pi}{180} = \\frac{\\pi}{4};$",
    "$150^{\\circ} = 150 \\cdot \\frac{\\pi}{180} = \\frac{5\\pi}{6}$.",
    "b) Ta có:",
    "$\\frac{\\pi}{3} = \\frac{\\pi}{3} \\left(\\frac{180}{\\pi}\\right)^{\\circ} = 60^{\\circ};$",
    "$\\frac{5\\pi}{4} = \\frac{5\\pi}{4} \\left(\\frac{180}{\\pi}\\right)^{\\circ} = 225^{\\circ}$.",
    "",
    "[Khung hình bên phải: Hình ảnh một bạn nữ nói: $\\alpha^{\\circ} = \\alpha \\cdot \\frac{\\pi}{180} \\text{ rad}$. Hình ảnh một bạn nam nói: $\\alpha \\text{ rad} = \\alpha \\cdot \\left(\\frac{180}{\\pi}\\right)^{\\circ}$.]",
    "",
    "**Luyện tập 3**",
    "a) Đổi từ độ sang radian các số đo sau: $360^{\\circ}; -450^{\\circ}$;",
    "b) Đổi từ radian sang độ các số đo sau: $3\\pi; -\\frac{11\\pi}{5}$.",
    "",
    "**Chú ý.** Dưới đây là bảng tương ứng giữa số đo bằng độ và số đo bằng radian của các góc đặc biệt trong phạm vi từ $0^{\\circ}$ đến $180^{\\circ}$.",
    "",
    "| Số đo độ | $0^{\\circ}$ | $30^{\\circ}$ | $45^{\\circ}$ | $60^{\\circ}$ | $90^{\\circ}$ | $120^{\\circ}$ | $135^{\\circ}$ | $150^{\\circ}$ | $180^{\\circ}$ |",
    "| :--- | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: |",
    "| Số đo radian | $0$ | $\\frac{\\pi}{6}$ | $\\frac{\\pi}{4}$ | $\\frac{\\pi}{3}$ | $\\frac{\\pi}{2}$ | $\\frac{2\\pi}{3}$ | $\\frac{3\\pi}{4}$ | $\\frac{5\\pi}{6}$ | $\\pi$ |",
    "",
    "### b) Độ dài cung tròn",
    "**HĐ3. Xây dựng công thức tính độ dài của cung tròn**",
    "Cho đường tròn bán kính $R$.",
    "a) Độ dài của cung tròn có số đo bằng 1 rad là bao nhiêu?",
    "b) Tính độ dài $l$ của cung tròn có số đo $\\alpha \\text{ rad}$.",
    "",
    "Một cung của đường tròn bán kính $R$ và có số đo $\\alpha \\text{ rad}$ thì có độ dài $l = R\\alpha$.",
    "",
    "**Ví dụ 4.** Cho đường tròn bán kính $2 \\text{ cm}$. Tính độ dài cung tròn có số đo $\\frac{2\\pi}{3}$ của đường tròn đó.",
    "**Giải**",
    "Độ dài của cung tròn đó là: $l = R\\alpha = 2 \\cdot \\frac{2\\pi}{3} = \\frac{4\\pi}{3} \\text{ (cm)}$.",
    "",
    "**Vận dụng 1.** Giải bài toán ở *tình huống mở đầu*.",
    "",
    "9",
    "## 3. GIÁ TRỊ LƯỢNG GIÁC CỦA GÓC LƯỢNG GIÁC",
    "",
    "### a) Đường tròn lượng giác",
    "**HĐ4. Nhận biết khái niệm đường tròn lượng giác**",
    "Trong mặt phẳng toạ độ $Oxy$, vẽ đường tròn tâm $O$ bán kính $R = 1$. Chọn điểm gốc của đường tròn là giao điểm $A(1; 0)$ của đường tròn với trục $Ox$. Ta quy ước chiều dương của đường tròn là chiều ngược chiều quay của kim đồng hồ và chiều âm là chiều quay của kim đồng hồ.",
    "a) Xác định điểm $M$ trên đường tròn sao cho $\\text{sđ}(OA, OM) = \\frac{5\\pi}{4}$.",
    "b) Xác định điểm $N$ trên đường tròn sao cho $\\text{sđ}(OA, ON) = -\\frac{7\\pi}{4}$.",
    "",
    "[Hình ảnh: Đường tròn đơn vị. Điểm $A$ trên trục hoành bên phải. Điểm $B$ trên trục tung phía trên. Điểm $A'$ trên trục hoành bên trái. Điểm $B'$ trên trục tung phía dưới. Có điểm $M$ trên đường tròn với góc $\\alpha$.]",
    "*Hình 1.7*",
    "",
    "| |",
    "| :--- |",
    "| • **Đường tròn lượng giác** là đường tròn có tâm tại gốc toạ độ, bán kính bằng 1, được định hướng và lấy điểm $A(1; 0)$ làm điểm gốc của đường tròn. |",
    "| • Điểm trên đường tròn lượng giác biểu diễn góc lượng giác có số đo $\\alpha$ (độ hoặc radian) là điểm $M$ trên đường tròn lượng giác sao cho $\\text{sđ}(OA, OM) = \\alpha$. |",
    "",
    "**Ví dụ 5.** Xác định các điểm $M$ và $N$ trên đường tròn lượng giác lần lượt biểu diễn các góc lượng giác có số đo bằng $\\frac{13\\pi}{4}$ và $-150^{\\circ}$.",
    "**Giải**",
    "Điểm $M$ trên đường tròn lượng giác biểu diễn góc lượng giác có số đo bằng $\\frac{13\\pi}{4}$ được xác định trong Hình 1.8.",
    "Điểm $N$ trên đường tròn lượng giác biểu diễn góc lượng giác có số đo bằng $-150^{\\circ}$ được xác định trong Hình 1.8.",
    "",
    "[Hình ảnh: Đường tròn lượng giác biểu diễn góc $\\frac{13\\pi}{4}$ (một vòng rưỡi rưỡi, điểm M ở góc phần tư thứ III) và góc $-150^{\\circ}$ (điểm N ở góc phần tư thứ III).]",
    "*Hình 1.8*",
    "",
    "**Luyện tập 4.** Xác định các điểm $M$ và $N$ trên đường tròn lượng giác lần lượt biểu diễn các góc lượng giác có số đo bằng $-\\frac{15\\pi}{4}$ và $420^{\\circ}$.",
    "",
    "10",
    "### b) Các giá trị lượng giác của góc lượng giác",
    "**HĐ5.** Nhắc lại khái niệm các giá trị lượng giác $\\sin \\alpha, \\cos \\alpha, \\tan \\alpha, \\cot \\alpha$ của góc $\\alpha$ $(0^{\\circ} \\le \\alpha \\le 180^{\\circ})$ đã học ở lớp 10 (H.1.9a).",
    "",
    "[Hình ảnh: a) Nửa đường tròn lượng giác tâm O, bán kính 1, từ trục $Ox$ (điểm $1$) sang trái đến $-1$. Điểm $M$ ở góc phần tư thứ hai, có hình chiếu $x_0$ trên trục hoành, $y_0$ trên trục tung. Có đánh dấu góc $\\alpha$ từ $Ox$ đến $OM$. b) Đường tròn lượng giác đầy đủ tâm $O$. Điểm $M(x; y)$ trên đường tròn tương ứng với góc $\\alpha$. Hình chiếu của $M$ trên $Oy$ là $\\sin \\alpha$, trên $Ox$ là $\\cos \\alpha$.]",
    "*Hình 1.9a* \\quad *Hình 1.9b*",
    "",
    "Ta có thể mở rộng khái niệm giá trị lượng giác cho các góc lượng giác có số đo tuỳ ý như sau:",
    "Giả sử $M(x; y)$ là điểm trên đường tròn lượng giác, biểu diễn góc lượng giác có số đo $\\alpha$ (H.1.9b).",
    "",
    "| |",
    "| :--- |",
    "| • Hoành độ $x$ của điểm $M$ được gọi là côsin của $\\alpha$, kí hiệu là $\\cos \\alpha$.<br>$\\cos \\alpha = x$.<br>• Tung độ $y$ của điểm $M$ được gọi là sin của $\\alpha$, kí hiệu là $\\sin \\alpha$.<br>$\\sin \\alpha = y$.<br>• Nếu $\\cos \\alpha \\neq 0$, tỉ số $\\frac{\\sin \\alpha}{\\cos \\alpha}$ được gọi là tang của $\\alpha$, kí hiệu là $\\tan \\alpha$.<br>$\\tan \\alpha = \\frac{\\sin \\alpha}{\\cos \\alpha} = \\frac{y}{x} \\, (x \\neq 0)$.<br>• Nếu $\\sin \\alpha \\neq 0$, tỉ số $\\frac{\\cos \\alpha}{\\sin \\alpha}$ được gọi là côtang của $\\alpha$, kí hiệu là $\\cot \\alpha$.<br>$\\cot \\alpha = \\frac{\\cos \\alpha}{\\sin \\alpha} = \\frac{x}{y} \\, (y \\neq 0)$.<br>• Các giá trị $\\cos \\alpha, \\sin \\alpha, \\tan \\alpha, \\cot \\alpha$ được gọi là các **giá trị lượng giác** của $\\alpha$. |",
    "",
    "**Chú ý**",
    "a) Ta còn gọi trục tung là trục sin, trục hoành là trục côsin.",
    "b) Từ định nghĩa ta suy ra:",
    "• $\\sin \\alpha, \\cos \\alpha$ xác định với mọi giá trị của $\\alpha$ và ta có:",
    "$-1 \\le \\sin \\alpha \\le 1; \\quad -1 \\le \\cos \\alpha \\le 1; \\quad \\sin(\\alpha + k2\\pi) = \\sin \\alpha; \\quad \\cos(\\alpha + k2\\pi) = \\cos \\alpha \\quad (k \\in \\mathbb{Z})$.",
    "• $\\tan \\alpha$ xác định khi $\\alpha \\neq \\frac{\\pi}{2} + k\\pi \\, (k \\in \\mathbb{Z})$.",
    "• $\\cot \\alpha$ xác định khi $\\alpha \\neq k\\pi \\, (k \\in \\mathbb{Z})$.",
    "",
    "11",
    "• Dấu của các giá trị lượng giác của một góc lượng giác phụ thuộc vào vị trí điểm biểu diễn $M$ trên đường tròn lượng giác (H.1.10).",
    "",
    "| Giá trị lượng giác \\ Góc phần tư | I | II | III | IV |",
    "| :--- | :---: | :---: | :---: | :---: |",
    "| $\\cos \\alpha$ | $+$ | $-$ | $-$ | $+$ |",
    "| $\\sin \\alpha$ | $+$ | $+$ | $-$ | $-$ |",
    "| $\\tan \\alpha$ | $+$ | $-$ | $+$ | $-$ |",
    "| $\\cot \\alpha$ | $+$ | $-$ | $+$ | $-$ |",
    "",
    "[Hình ảnh: Đường tròn lượng giác với 4 góc phần tư I, II, III, IV được ghi rõ ràng.]",
    "*Hình 1.10*",
    "",
    "**Ví dụ 6.** Cho góc lượng giác có số đo bằng $-\\frac{\\pi}{3}$.",
    "a) Xác định điểm $M$ trên đường tròn lượng giác biểu diễn góc lượng giác đã cho.",
    "b) Tính các giá trị lượng giác của góc lượng giác đã cho.",
    "**Giải**",
    "a) Điểm $M$ trên đường tròn lượng giác biểu diễn góc lượng giác có số đo là $-\\frac{\\pi}{3}$ được xác định trong Hình 1.11.",
    "b) Ta có:",
    "$\\cos\\left(-\\frac{\\pi}{3}\\right) = \\frac{1}{2}; \\sin\\left(-\\frac{\\pi}{3}\\right) = -\\frac{\\sqrt{3}}{2};$",
    "$\\tan\\left(-\\frac{\\pi}{3}\\right) = \\frac{\\sin\\left(-\\frac{\\pi}{3}\\right)}{\\cos\\left(-\\frac{\\pi}{3}\\right)} = -\\sqrt{3}; \\cot\\left(-\\frac{\\pi}{3}\\right) = \\frac{\\cos\\left(-\\frac{\\pi}{3}\\right)}{\\sin\\left(-\\frac{\\pi}{3}\\right)} = -\\frac{1}{\\sqrt{3}}$.",
    "",
    "[Hình ảnh: Đường tròn lượng giác biểu diễn góc $-\\frac{\\pi}{3}$, điểm M nằm ở góc phần tư thứ tư với hoành độ $\\frac{1}{2}$ và tung độ $-\\frac{\\sqrt{3}}{2}$.]",
    "*Hình 1.11*",
    "",
    "**Luyện tập 5.** Cho góc lượng giác có số đo bằng $\\frac{5\\pi}{6}$.",
    "a) Xác định điểm $M$ trên đường tròn lượng giác biểu diễn góc lượng giác đã cho.",
    "b) Tính các giá trị lượng giác của góc lượng giác đã cho.",
    "",
    "### c) Giá trị lượng giác của các góc đặc biệt",
    "",
    "| Góc $\\alpha$ | $0$ | $\\frac{\\pi}{6}$ | $\\frac{\\pi}{4}$ | $\\frac{\\pi}{3}$ | $\\frac{\\pi}{2}$ |",
    "| :--- | :---: | :---: | :---: | :---: | :---: |",
    "| | $0^{\\circ}$ | $30^{\\circ}$ | $45^{\\circ}$ | $60^{\\circ}$ | $90^{\\circ}$ |",
    "| $\\sin \\alpha$ | $0$ | $\\frac{1}{2}$ | $\\frac{\\sqrt{2}}{2}$ | $\\frac{\\sqrt{3}}{2}$ | $1$ |",
    "| $\\cos \\alpha$ | $1$ | $\\frac{\\sqrt{3}}{2}$ | $\\frac{\\sqrt{2}}{2}$ | $\\frac{1}{2}$ | $0$ |",
    "| $\\tan \\alpha$ | $0$ | $\\frac{1}{\\sqrt{3}}$ | $1$ | $\\sqrt{3}$ | Không xác định |",
    "| $\\cot \\alpha$ | Không xác định | $\\sqrt{3}$ | $1$ | $\\frac{1}{\\sqrt{3}}$ | $0$ |",
    "",
    "12",
    "### d) Sử dụng máy tính cầm tay để đổi số đo góc và tìm giá trị lượng giác của góc",
    "Có thể dùng máy tính cầm tay để tính giá trị lượng giác của góc lượng giác và đổi số đo độ của cung tròn ra radian và ngược lại.",
    "",
    "**Ví dụ 7.** Sử dụng máy tính cầm tay để tính: $\\sin\\left(-\\frac{9\\pi}{4}\\right)$; $\\tan 63^{\\circ}52'41''$ (làm tròn kết quả đến chữ số thập phân thứ tư).",
    "**Giải**",
    "",
    "| Tính | Bấm phím | Màn hình hiện | Kết quả |",
    "| :--- | :--- | :---: | :---: |",
    "| $\\sin\\left(-\\frac{9\\pi}{4}\\right)$ | [SHIFT] [MODE] [4] [sin] [(-)] [9] [SHIFT] [$\\pi$] [$\\div$] [4] [)] [=] | $-\\frac{\\sqrt{2}}{2}$ | $-0,7071$ |",
    "| $\\tan 63^{\\circ}52'41''$ | [SHIFT] [MODE] [3] [tan] [6] [3] [°'''] [5] [2] [°'''] [4] [1] [°'''] [)] [=] | $2.039276645$ | $2,0393$ |",
    "",
    "**Ví dụ 8.** a) Đổi $33^{\\circ}45'$ sang radian; \\qquad b) Đổi $\\frac{3}{4}$ (rad) sang độ.",
    "**Giải**",
    "",
    "| Đổi số đo | Bấm phím | Màn hình hiện | Kết quả |",
    "| :--- | :--- | :---: | :---: |",
    "| $33^{\\circ}45'$ | [SHIFT] [MODE] [2] [3] [3] [°'''] [4] [5] [°'''] [SHIFT] (DRG $\\blacktriangleright$) [1] [=] | $\\frac{3}{16}\\pi$ | $\\frac{3}{16}\\pi \\text{ (rad)}$ |",
    "| $\\frac{3}{4} \\text{ (rad)}$ | [SHIFT] [MODE] [3] [(] [3] [$\\div$] [4] [)] [SHIFT] (DRG $\\blacktriangleright$) [2] [=] [°'''] | $42^{\\circ}58'18.6''$ | $42^{\\circ}58'19''$ |",
    "",
    "**Luyện tập 6.** Sử dụng máy tính cầm tay để:",
    "a) Tính: $\\cos \\frac{3\\pi}{7}; \\tan(-37^{\\circ}25')$;",
    "b) Đổi $179^{\\circ}23'30''$ sang radian;",
    "c) Đổi $\\frac{7}{9} \\text{ (rad)}$ sang độ.",
    "",
    "## 4. QUAN HỆ GIỮA CÁC GIÁ TRỊ LƯỢNG GIÁC",
    "",
    "### a) Các công thức lượng giác cơ bản",
    "**HĐ6. Nhận biết các công thức lượng giác cơ bản**",
    "a) Dựa vào định nghĩa của $\\sin \\alpha$ và $\\cos \\alpha$, hãy tính $\\sin^2 \\alpha + \\cos^2 \\alpha$.",
    "b) Sử dụng kết quả của HĐ6a và định nghĩa của $\\tan \\alpha$, hãy tính $1 + \\tan^2 \\alpha$.",
    "",
    "13",
    "Đối với các giá trị lượng giác, ta có các **hệ thức cơ bản** sau:",
    "",
    "| |",
    "| :--- |",
    "| $\\sin^2 \\alpha + \\cos^2 \\alpha = 1$ <br> $1 + \\tan^2 \\alpha = \\frac{1}{\\cos^2 \\alpha} \\quad \\left(\\alpha \\neq \\frac{\\pi}{2} + k\\pi, k \\in \\mathbb{Z}\\right)$ <br> $1 + \\cot^2 \\alpha = \\frac{1}{\\sin^2 \\alpha} \\quad (\\alpha \\neq k\\pi, k \\in \\mathbb{Z})$ <br> $\\tan \\alpha \\cdot \\cot \\alpha = 1 \\quad \\left(\\alpha \\neq \\frac{k\\pi}{2}, k \\in \\mathbb{Z}\\right)$ |",
    "",
    "**Ví dụ 9.** Tính các giá trị lượng giác của góc $\\alpha$, biết: $\\sin \\alpha = \\frac{3}{5}$ và $90^{\\circ} < \\alpha < 180^{\\circ}$.",
    "**Giải**",
    "Vì $90^{\\circ} < \\alpha < 180^{\\circ}$ nên $\\cos \\alpha < 0$. Mặt khác, từ $\\sin^2 \\alpha + \\cos^2 \\alpha = 1$ suy ra",
    "$\\cos \\alpha = -\\sqrt{1 - \\sin^2 \\alpha} = -\\sqrt{1 - \\frac{9}{25}} = -\\frac{4}{5}$.",
    "Do đó, $\\tan \\alpha = \\frac{\\sin \\alpha}{\\cos \\alpha} = \\frac{\\frac{3}{5}}{-\\frac{4}{5}} = -\\frac{3}{4}$ và $\\cot \\alpha = \\frac{1}{\\tan \\alpha} = \\frac{1}{-\\frac{3}{4}} = -\\frac{4}{3}$.",
    "",
    "**Luyện tập 7.** Tính các giá trị lượng giác của góc $\\alpha$, biết: $\\cos \\alpha = -\\frac{2}{3}$ và $\\pi < \\alpha < \\frac{3\\pi}{2}$.",
    "",
    "### b) Giá trị lượng giác của các góc có liên quan đặc biệt",
    "**HĐ7. Nhận biết liên hệ giữa giá trị lượng giác của các góc đối nhau**",
    "Xét hai điểm $M, N$ trên đường tròn lượng giác xác định bởi hai góc đối nhau (H1.12a).",
    "a) Có nhận xét gì về vị trí của hai điểm $M, N$ đối với hệ trục $Oxy$? Từ đó rút ra liên hệ giữa: $\\cos(-\\alpha)$ và $\\cos \\alpha$; $\\sin(-\\alpha)$ và $\\sin \\alpha$.",
    "b) Từ kết quả HĐ7a, rút ra liên hệ giữa: $\\tan(-\\alpha)$ và $\\tan \\alpha$; $\\cot(-\\alpha)$ và $\\cot \\alpha$.",
    "Với kết quả HĐ7, ta có liên hệ giữa các giá trị lượng giác:",
    "- Góc đối nhau ($\\alpha$ và $-\\alpha$)",
    "",
    "| |",
    "| :--- |",
    "| $\\cos(-\\alpha) = \\cos \\alpha$ <br> $\\sin(-\\alpha) = -\\sin \\alpha$ <br> $\\tan(-\\alpha) = -\\tan \\alpha$ <br> $\\cot(-\\alpha) = -\\cot \\alpha$ |",
    "",
    "[Hình ảnh: Đường tròn lượng giác có hai điểm M và N đối xứng nhau qua trục hoành $Ox$. Điểm M tương ứng với góc $\\alpha$, điểm N tương ứng với góc $-\\alpha$. Cả hai điểm M và N đều có cùng hoành độ.]",
    "*Hình 1.12a*",
    "",
    "14",
    "Tương tự HĐ7, ta cũng có liên hệ giữa giá trị lượng giác của các góc bù nhau, phụ nhau và hơn kém $\\pi$, như sau:",
    "",
    "- Góc bù nhau ($\\alpha$ và $\\pi - \\alpha$)",
    "| |",
    "| :--- |",
    "| $\\sin(\\pi - \\alpha) = \\sin \\alpha$ <br> $\\cos(\\pi - \\alpha) = -\\cos \\alpha$ <br> $\\tan(\\pi - \\alpha) = -\\tan \\alpha$ <br> $\\cot(\\pi - \\alpha) = -\\cot \\alpha$ |",
    "",
    "[Hình ảnh: Đường tròn lượng giác biểu diễn hai góc bù nhau $\\alpha$ và $\\pi - \\alpha$. Hai điểm $M$ và $N$ đối xứng qua trục tung $Oy$.]",
    "*Hình 1.12b*",
    "",
    "- Góc phụ nhau ($\\alpha$ và $\\frac{\\pi}{2} - \\alpha$)",
    "| |",
    "| :--- |",
    "| $\\sin\\left(\\frac{\\pi}{2} - \\alpha\\right) = \\cos \\alpha$ <br> $\\cos\\left(\\frac{\\pi}{2} - \\alpha\\right) = \\sin \\alpha$ <br> $\\tan\\left(\\frac{\\pi}{2} - \\alpha\\right) = \\cot \\alpha$ <br> $\\cot\\left(\\frac{\\pi}{2} - \\alpha\\right) = \\tan \\alpha$ |",
    "",
    "[Hình ảnh: Đường tròn lượng giác biểu diễn hai góc phụ nhau $\\alpha$ và $\\frac{\\pi}{2} - \\alpha$. Hai điểm $M$ và $N$ đối xứng qua đường phân giác của góc phần tư thứ nhất.]",
    "*Hình 1.12c*",
    "",
    "- Góc hơn kém $\\pi$ ($\\alpha$ và $\\pi + \\alpha$)",
    "| |",
    "| :--- |",
    "| $\\sin(\\pi + \\alpha) = -\\sin \\alpha$ <br> $\\cos(\\pi + \\alpha) = -\\cos \\alpha$ <br> $\\tan(\\pi + \\alpha) = \\tan \\alpha$ <br> $\\cot(\\pi + \\alpha) = \\cot \\alpha$ |",
    "",
    "[Hình ảnh: Đường tròn lượng giác biểu diễn hai góc hơn kém $\\pi$ là $\\alpha$ và $\\pi + \\alpha$. Hai điểm $M$ và $N$ đối xứng qua gốc toạ độ $O$.]",
    "*Hình 1.12d*",
    "",
    "**Chú ý.** Nhờ các công thức trên, ta có thể đưa việc tính giá trị lượng giác của một góc lượng giác bất kì về việc tính giá trị lượng giác của góc $\\alpha$ với $0 \\le \\alpha \\le \\frac{\\pi}{2}$.",
    "",
    "**Ví dụ 10.** Tính: \\quad a) $\\cos\\left(-\\frac{11\\pi}{4}\\right)$; \\qquad b) $\\cot(-675^{\\circ})$.",
    "**Giải.** Ta có:",
    "a) $\\cos\\left(-\\frac{11\\pi}{4}\\right) = \\cos\\frac{11\\pi}{4} = \\cos\\left(\\frac{3\\pi}{4} + 2\\pi\\right) = \\cos\\frac{3\\pi}{4} = -\\cos\\left(\\pi - \\frac{3\\pi}{4}\\right) = -\\cos\\frac{\\pi}{4} = -\\frac{\\sqrt{2}}{2}$.",
    "b) $\\cot(-675^{\\circ}) = \\cot(45^{\\circ} - 2 \\cdot 360^{\\circ}) = \\cot 45^{\\circ} = 1$.",
    "",
    "**Luyện tập 8.** Tính: \\quad a) $\\sin(-675^{\\circ})$; \\qquad b) $\\tan\\frac{15\\pi}{4}$.",
    "",
    "15",
    "**Vận dụng 2.** Huyết áp của mỗi người thay đổi trong ngày. Giả sử huyết áp tâm trương (tức là áp lực máu lên thành động mạch khi tim giãn ra) của một người nào đó ở trạng thái nghỉ ngơi tại thời điểm $t$ được cho bởi công thức:",
    "$$B(t) = 80 + 7\\sin\\frac{\\pi t}{12},$$",
    "trong đó $t$ là số giờ tính từ lúc nửa đêm và $B(t)$ tính bằng mmHg (milimét thuỷ ngân). Tìm huyết áp tâm trương của người này vào các thời điểm sau:",
    "a) 6 giờ sáng; \\qquad b) 10 giờ 30 phút sáng; \\qquad c) 12 giờ trưa; \\qquad d) 8 giờ tối.",
    "",
    "# BÀI TẬP",
    "",
    "**1.1.** Hoàn thành bảng sau:",
    "",
    "| Số đo độ | $15^{\\circ}$ | ? | $0^{\\circ}$ | $900^{\\circ}$ | ? | ? |",
    "| :--- | :---: | :---: | :---: | :---: | :---: | :---: |",
    "| Số đo radian | ? | $\\frac{3\\pi}{8}$ | ? | ? | $\\frac{7\\pi}{12}$ | $-\\frac{11\\pi}{8}$ |",
    "",
    "**1.2.** Một đường tròn có bán kính $20 \\text{ cm}$. Tìm độ dài của các cung trên đường tròn đó có số đo sau:",
    "a) $\\frac{\\pi}{12}$; \\qquad b) 1,5; \\qquad c) $35^{\\circ}$; \\qquad d) $315^{\\circ}$.",
    "",
    "**1.3.** Trên đường tròn lượng giác, xác định điểm biểu diễn các góc lượng giác có số đo sau:",
    "a) $\\frac{2\\pi}{3}$; \\qquad b) $-\\frac{11\\pi}{4}$; \\qquad c) $150^{\\circ}$; \\qquad d) $-225^{\\circ}$.",
    "",
    "**1.4.** Tính các giá trị lượng giác của góc $\\alpha$, biết:",
    "a) $\\cos \\alpha = \\frac{1}{5}$ và $0 < \\alpha < \\frac{\\pi}{2}$; \\qquad b) $\\sin \\alpha = \\frac{2}{3}$ và $\\frac{\\pi}{2} < \\alpha < \\pi$;",
    "c) $\\tan \\alpha = \\sqrt{5}$ và $\\pi < \\alpha < \\frac{3\\pi}{2}$; \\qquad d) $\\cot \\alpha = -\\frac{1}{\\sqrt{2}}$ và $\\frac{3\\pi}{2} < \\alpha < 2\\pi$.",
    "",
    "**1.5.** Chứng minh các đẳng thức:",
    "a) $\\cos^4 \\alpha - \\sin^4 \\alpha = 2\\cos^2 \\alpha - 1$; \\qquad b) $\\frac{\\cos^2 \\alpha + \\tan^2 \\alpha - 1}{\\sin^2 \\alpha} = \\tan^2 \\alpha$.",
    "",
    "**1.6.** Một người đi xe đạp với vận tốc không đổi, biết rằng bánh xe đạp quay được 11 vòng trong 5 giây.",
    "a) Tính góc (theo độ và radian) mà bánh xe quay được trong 1 giây.",
    "b) Tính độ dài quãng đường mà người đi xe đã đi được trong 1 phút, biết rằng đường kính của bánh xe đạp là 680 mm.",
    "",
    "16"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN11_T1')), 'B2', 'Công thức lượng giác', 17, 2, $JSON$
{
  "content": [
    "# Bài 2. CÔNG THỨC LƯỢNG GIÁC",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Công thức cộng<br>• Công thức nhân đôi<br>• Công thức biến đổi tích thành tổng<br>• Công thức biến đổi tổng thành tích | • Mô tả các phép biến đổi lượng giác cơ bản: công thức cộng; công thức góc nhân đôi; công thức biến đổi tích thành tổng và công thức biến đổi tổng thành tích.<br>• Giải quyết một số vấn đề thực tiễn gắn với giá trị lượng giác của góc lượng giác và các phép biến đổi lượng giác. |",
    "",
    "Một thiết bị trễ kĩ thuật số lặp lại tín hiệu đầu vào bằng cách lặp lại tín hiệu đó trong một khoảng thời gian cố định sau khi nhận được tín hiệu. Nếu một thiết bị như vậy nhận được nốt thuần $f_1(t) = 5\\sin t$ và phát lại được nốt thuần $f_2(t) = 5\\cos t$ thì âm kết hợp là $f(t) = f_1(t) + f_2(t)$, trong đó $t$ là biến thời gian. Chứng tỏ rằng âm kết hợp viết được dưới dạng $f(t) = k\\sin(t + \\varphi)$, tức là âm kết hợp là một sóng âm hình sin. Hãy xác định biên độ âm $k$ và pha ban đầu $\\varphi$ $(-\\pi \\le \\varphi \\le \\pi)$ của sóng âm.",
    "",
    "## 1. CÔNG THỨC CỘNG",
    "**HĐ1. Nhận biết công thức cộng**",
    "a) Cho $a = \\frac{\\pi}{3}$ và $b = \\frac{\\pi}{6}$, hãy chứng tỏ $\\cos(a - b) = \\cos a \\cos b + \\sin a \\sin b$.",
    "b) Bằng cách viết $a + b = a - (-b)$ và từ công thức ở HĐ1a, hãy tính $\\cos(a + b)$.",
    "c) Bằng cách viết $\\sin(a - b) = \\cos\\left[\\frac{\\pi}{2} - (a - b)\\right] = \\cos\\left[\\left(\\frac{\\pi}{2} - a\\right) + b\\right]$ và sử dụng công thức vừa thiết lập ở HĐ1b, hãy tính $\\sin(a - b)$.",
    "",
    "| |",
    "| :--- |",
    "| $\\cos(a - b) = \\cos a \\cos b + \\sin a \\sin b$ <br> $\\cos(a + b) = \\cos a \\cos b - \\sin a \\sin b$ <br> $\\sin(a - b) = \\sin a \\cos b - \\cos a \\sin b$ <br> $\\sin(a + b) = \\sin a \\cos b + \\cos a \\sin b$ <br> $\\tan(a - b) = \\frac{\\tan a - \\tan b}{1 + \\tan a \\tan b}$ <br> $\\tan(a + b) = \\frac{\\tan a + \\tan b}{1 - \\tan a \\tan b}$ <br> (giả thiết các biểu thức đều có nghĩa). |",
    "",
    "**Ví dụ 1.** Không dùng máy tính, hãy tính:",
    "a) $\\cos 75^{\\circ}$; \\qquad b) $\\tan\\frac{\\pi}{12}$.",
    "",
    "17",
    "**Giải**",
    "a) $\\cos 75^{\\circ} = \\cos(45^{\\circ} + 30^{\\circ}) = \\cos 45^{\\circ} \\cos 30^{\\circ} - \\sin 45^{\\circ} \\sin 30^{\\circ} = \\frac{\\sqrt{2}}{2} \\cdot \\frac{\\sqrt{3}}{2} - \\frac{\\sqrt{2}}{2} \\cdot \\frac{1}{2} = \\frac{\\sqrt{6} - \\sqrt{2}}{4}$.",
    "b) $\\tan\\frac{\\pi}{12} = \\tan\\left(\\frac{\\pi}{3} - \\frac{\\pi}{4}\\right) = \\frac{\\tan\\frac{\\pi}{3} - \\tan\\frac{\\pi}{4}}{1 + \\tan\\frac{\\pi}{3}\\tan\\frac{\\pi}{4}} = \\frac{\\sqrt{3} - 1}{1 + \\sqrt{3}} = \\frac{(\\sqrt{3} - 1)^2}{3 - 1} = 2 - \\sqrt{3}$.",
    "",
    "**Ví dụ 2.** Chứng minh rằng $\\sin x + \\cos x = \\sqrt{2} \\sin\\left(x + \\frac{\\pi}{4}\\right)$.",
    "**Giải**",
    "Ta có",
    "$\\sqrt{2} \\sin\\left(x + \\frac{\\pi}{4}\\right) = \\sqrt{2}\\left(\\sin x \\cos\\frac{\\pi}{4} + \\cos x \\sin\\frac{\\pi}{4}\\right) = \\sqrt{2}\\left(\\sin x \\cdot \\frac{\\sqrt{2}}{2} + \\cos x \\cdot \\frac{\\sqrt{2}}{2}\\right) = \\sin x + \\cos x$.",
    "Đẳng thức được chứng minh.",
    "",
    "**Luyện tập 1.** Chứng minh rằng:",
    "a) $\\sin x - \\cos x = \\sqrt{2}\\sin\\left(x - \\frac{\\pi}{4}\\right)$;",
    "b) $\\tan\\left(\\frac{\\pi}{4} - x\\right) = \\frac{1 - \\tan x}{1 + \\tan x} \\quad \\left(x \\neq \\frac{\\pi}{2} + k\\pi, x \\neq -\\frac{3\\pi}{4} + k\\pi, k \\in \\mathbb{Z}\\right)$.",
    "",
    "**Vận dụng 1.** Giải bài toán trong *tình huống mở đầu*.",
    "",
    "## 2. CÔNG THỨC NHÂN ĐÔI",
    "**HĐ2. Xây dựng công thức nhân đôi**",
    "Lấy $b = a$ trong các công thức cộng, hãy tìm công thức tính: $\\sin 2a; \\cos 2a; \\tan 2a$.",
    "",
    "| |",
    "| :--- |",
    "| $\\sin 2a = 2\\sin a \\cos a$ <br> $\\cos 2a = \\cos^2 a - \\sin^2 a = 2\\cos^2 a - 1 = 1 - 2\\sin^2 a$ <br> $\\tan 2a = \\frac{2\\tan a}{1 - \\tan^2 a}$ |",
    "",
    "**Ví dụ 3.** Cho $\\cos a = -\\frac{1}{3} \\left(\\frac{\\pi}{2} < a < \\pi\\right)$. Tính $\\sin 2a$.",
    "**Giải**",
    "Vì $\\frac{\\pi}{2} < a < \\pi$ nên $\\sin a > 0$. Do đó $\\sin a = \\sqrt{1 - \\cos^2 a} = \\sqrt{1 - \\left(-\\frac{1}{3}\\right)^2} = \\sqrt{1 - \\frac{1}{9}} = \\frac{\\sqrt{8}}{3} = \\frac{2\\sqrt{2}}{3}$.",
    "",
    "Vậy $\\sin 2a = 2\\sin a \\cos a = 2 \\cdot \\frac{2\\sqrt{2}}{3} \\cdot \\left(-\\frac{1}{3}\\right) = -\\frac{4\\sqrt{2}}{9}$.",
    "",
    "18",
    "**Luyện tập 2.** Không dùng máy tính, tính $\\cos\\frac{\\pi}{8}$.",
    "",
    "[Khung chữ bên lề: Hình ảnh một rô-bốt nhỏ. \"Công thức hạ bậc: $\\cos^2 a = \\frac{1 + \\cos 2a}{2}$; $\\sin^2 a = \\frac{1 - \\cos 2a}{2}$.\"]",
    "",
    "## 3. CÔNG THỨC BIẾN ĐỔI TÍCH THÀNH TỔNG",
    "**HĐ3. Xây dựng công thức biến đổi tích thành tổng**",
    "a) Từ các công thức cộng $\\cos(a + b)$ và $\\cos(a - b)$, hãy tìm: $\\cos a \\cos b; \\sin a \\sin b$.",
    "b) Từ các công thức cộng $\\sin(a + b)$ và $\\sin(a - b)$, hãy tìm: $\\sin a \\cos b$.",
    "",
    "| |",
    "| :--- |",
    "| $\\cos a \\cos b = \\frac{1}{2}[\\cos(a - b) + \\cos(a + b)]$ <br> $\\sin a \\sin b = \\frac{1}{2}[\\cos(a - b) - \\cos(a + b)]$ <br> $\\sin a \\cos b = \\frac{1}{2}[\\sin(a - b) + \\sin(a + b)]$. |",
    "",
    "**Ví dụ 4.** Tính giá trị của các biểu thức:",
    "$A = \\cos\\frac{5\\pi}{12} \\cos\\frac{7\\pi}{12}; \\qquad B = \\cos 75^{\\circ} \\sin 15^{\\circ}$.",
    "**Giải**",
    "Ta có:",
    "$A = \\cos\\frac{5\\pi}{12} \\cos\\frac{7\\pi}{12} = \\frac{1}{2}\\left[\\cos\\left(\\frac{5\\pi}{12} - \\frac{7\\pi}{12}\\right) + \\cos\\left(\\frac{5\\pi}{12} + \\frac{7\\pi}{12}\\right)\\right]$",
    "$= \\frac{1}{2}\\left[\\cos\\left(-\\frac{\\pi}{6}\\right) + \\cos\\pi\\right] = \\frac{1}{2}\\left(\\frac{\\sqrt{3}}{2} - 1\\right) = \\frac{\\sqrt{3} - 2}{4}$.",
    "",
    "$B = \\sin 15^{\\circ} \\cdot \\cos 75^{\\circ} = \\frac{1}{2}[\\sin(15^{\\circ} - 75^{\\circ}) + \\sin(15^{\\circ} + 75^{\\circ})]$",
    "$= \\frac{1}{2}[\\sin(-60^{\\circ}) + \\sin 90^{\\circ}] = \\frac{1}{2}\\left(-\\frac{\\sqrt{3}}{2} + 1\\right) = \\frac{2 - \\sqrt{3}}{4}$.",
    "",
    "**Luyện tập 3.** Không dùng máy tính, tính giá trị của các biểu thức:",
    "$A = \\cos 75^{\\circ} \\cos 15^{\\circ}; \\qquad B = \\sin\\frac{5\\pi}{12} \\cos\\frac{7\\pi}{12}$.",
    "",
    "19",
    "## 4. CÔNG THỨC BIẾN ĐỔI TỔNG THÀNH TÍCH",
    "**HĐ4. Xây dựng công thức biến đổi tổng thành tích**",
    "Trong các công thức biến đổi tích thành tổng ở Mục 3, đặt $u = a - b, v = a + b$ và viết các công thức nhận được.",
    "",
    "| |",
    "| :--- |",
    "| $\\cos u + \\cos v = 2\\cos\\frac{u + v}{2} \\cos\\frac{u - v}{2}$ <br> $\\cos u - \\cos v = -2\\sin\\frac{u + v}{2} \\sin\\frac{u - v}{2}$ <br> $\\sin u + \\sin v = 2\\sin\\frac{u + v}{2} \\cos\\frac{u - v}{2}$ <br> $\\sin u - \\sin v = 2\\cos\\frac{u + v}{2} \\sin\\frac{u - v}{2}$. |",
    "",
    "**Ví dụ 5.** Không dùng máy tính, tính giá trị của biểu thức $A = \\sin\\frac{\\pi}{9} - \\sin\\frac{4\\pi}{9} + \\sin\\frac{7\\pi}{9}$.",
    "**Giải**",
    "$A = \\left(\\sin\\frac{\\pi}{9} + \\sin\\frac{7\\pi}{9}\\right) - \\sin\\frac{4\\pi}{9} = 2\\sin\\frac{4\\pi}{9} \\cos\\frac{\\pi}{3} - \\sin\\frac{4\\pi}{9} = \\sin\\frac{4\\pi}{9} - \\sin\\frac{4\\pi}{9} = 0$.",
    "",
    "**Luyện tập 4.** Không dùng máy tính, tính giá trị của biểu thức",
    "$B = \\cos\\frac{\\pi}{9} + \\cos\\frac{5\\pi}{9} + \\cos\\frac{11\\pi}{9}$.",
    "",
    "**Vận dụng 2.** Khi nhấn một phím trên điện thoại cảm ứng, bàn phím sẽ tạo ra hai âm thuần, kết hợp với nhau để tạo ra âm thanh nhận dạng duy nhất phím. Hình 1.13 cho thấy tần số thấp $f_1$ và tần số cao $f_2$ liên quan đến mỗi phím. Nhấn một phím sẽ tạo ra sóng âm $y = \\sin(2\\pi f_1 t) + \\sin(2\\pi f_2 t)$, ở đó $t$ là biến thời gian (tính bằng giây).",
    "a) Tìm hàm số mô hình hoá âm thanh được tạo ra khi nhấn phím 4.",
    "b) Biến đổi công thức vừa tìm được ở câu a về dạng tích của một hàm số sin và một hàm số côsin.",
    "",
    "[Hình ảnh: Sơ đồ bàn phím điện thoại với các tần số. ",
    "Tần số thấp (hàng ngang): ",
    "697 Hz $\\rightarrow$ 1, 2, 3",
    "770 Hz $\\rightarrow$ 4, 5, 6",
    "852 Hz $\\rightarrow$ 7, 8, 9",
    "941 Hz $\\rightarrow$ *, 0, #",
    "Tần số cao (cột dọc):",
    "1209 Hz $\\downarrow$ 1, 4, 7, *",
    "1336 Hz $\\downarrow$ 2, 5, 8, 0",
    "1477 Hz $\\downarrow$ 3, 6, 9, #",
    "]",
    "*Hình 1.13*",
    "",
    "20",
    "# BÀI TẬP",
    "",
    "**1.7.** Sử dụng $15^{\\circ} = 45^{\\circ} - 30^{\\circ}$, hãy tính các giá trị lượng giác của góc $15^{\\circ}$.",
    "",
    "**1.8.** Tính:",
    "a) $\\cos\\left(a + \\frac{\\pi}{6}\\right)$, biết $\\sin a = \\frac{1}{\\sqrt{3}}$ và $\\frac{\\pi}{2} < a < \\pi$;",
    "b) $\\tan\\left(a - \\frac{\\pi}{4}\\right)$, biết $\\cos a = -\\frac{1}{3}$ và $\\pi < a < \\frac{3\\pi}{2}$.",
    "",
    "**1.9.** Tính $\\sin 2a, \\cos 2a, \\tan 2a$, biết:",
    "a) $\\sin a = \\frac{1}{3}$ và $\\frac{\\pi}{2} < a < \\pi$; \\qquad b) $\\sin a + \\cos a = \\frac{1}{2}$ và $\\frac{\\pi}{2} < a < \\frac{3\\pi}{4}$.",
    "",
    "**1.10.** Tính giá trị của các biểu thức sau:",
    "a) $A = \\frac{\\sin\\frac{\\pi}{15}\\cos\\frac{\\pi}{10} + \\sin\\frac{\\pi}{10}\\cos\\frac{\\pi}{15}}{\\cos\\frac{2\\pi}{15}\\cos\\frac{\\pi}{5} - \\sin\\frac{2\\pi}{15}\\sin\\frac{\\pi}{5}}$; \\qquad b) $B = \\sin\\frac{\\pi}{32}\\cos\\frac{\\pi}{32}\\cos\\frac{\\pi}{16}\\cos\\frac{\\pi}{8}$.",
    "",
    "**1.11.** Chứng minh đẳng thức sau:",
    "$\\sin(a + b)\\sin(a - b) = \\sin^2 a - \\sin^2 b = \\cos^2 b - \\cos^2 a$.",
    "",
    "**1.12.** Cho tam giác $ABC$ có $\\widehat{B} = 75^{\\circ}; \\widehat{C} = 45^{\\circ}$ và $a = BC = 12 \\text{ cm}$.",
    "a) Sử dụng công thức $S = \\frac{1}{2}ab\\sin C$ và định lí sin, hãy chứng minh diện tích của tam giác $ABC$ cho bởi công thức",
    "$S = \\frac{a^2\\sin B\\sin C}{2\\sin A}$.",
    "b) Sử dụng kết quả ở câu a và công thức biến đổi tích thành tổng, hãy tính diện tích $S$ của tam giác $ABC$.",
    "",
    "**1.13.** Trong Vật lí, phương trình tổng quát của một vật dao động điều hoà cho bởi công thức $x(t) = A\\cos(\\omega t + \\varphi)$, trong đó $t$ là thời điểm (tính bằng giây), $x(t)$ là li độ của vật tại thời điểm $t$, $A$ là biên độ dao động ($A > 0$) và $\\varphi \\in [-\\pi; \\pi]$ là pha ban đầu của dao động.",
    "Xét hai dao động điều hoà có phương trình:",
    "$x_1(t) = 2\\cos\\left(\\frac{\\pi}{3}t + \\frac{\\pi}{6}\\right) \\text{ (cm)}$,",
    "$x_2(t) = 2\\cos\\left(\\frac{\\pi}{3}t - \\frac{\\pi}{3}\\right) \\text{ (cm)}$.",
    "Tìm dao động tổng hợp $x(t) = x_1(t) + x_2(t)$ và sử dụng công thức biến đổi tổng thành tích để tìm biên độ và pha ban đầu của dao động tổng hợp này.",
    "",
    "21"
  ]
}
