{
  "content": [
    "# Bài 3. HÀM SỐ LƯỢNG GIÁC",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Hàm số lượng giác<br>• Hàm số chẵn<br>• Hàm số lẻ<br>• Hàm số tuần hoàn<br>• Đồ thị của hàm số lượng giác | • Nhận biết các khái niệm về hàm số chẵn, hàm số lẻ, hàm số tuần hoàn.<br>• Nhận biết các đặc trưng hình học của đồ thị hàm số chẵn, hàm số lẻ, hàm số tuần hoàn.<br>• Nhận biết các hàm số lượng giác $y = \\sin x, y = \\cos x, y = \\tan x, y = \\cot x$ thông qua đường tròn lượng giác. Mô tả bảng giá trị của bốn hàm số lượng giác đó trên một chu kì.<br>• Vẽ đồ thị của các hàm số $y = \\sin x, y = \\cos x, y = \\tan x, y = \\cot x$.<br>• Giải thích tập xác định; tập giá trị; tính chất chẵn, lẻ; tính tuần hoàn; chu kì; khoảng đồng biến, nghịch biến của các hàm số $y = \\sin x, y = \\cos x, y = \\tan x, y = \\cot x$ dựa vào đồ thị.<br>• Giải quyết một số vấn đề thực tiễn gắn với hàm số lượng giác. |",
    "",
    "Giả sử vận tốc $v$ (tính bằng lít/giây) của luồng khí trong một chu kì hô hấp (tức là thời gian từ lúc bắt đầu của một nhịp thở đến khi bắt đầu của nhịp thở tiếp theo) của một người nào đó ở trạng thái nghỉ ngơi được cho bởi công thức",
    "$v = 0,85\\sin\\frac{\\pi t}{3}$,",
    "trong đó $t$ là thời gian (tính bằng giây). Hãy tìm thời gian của một chu kì hô hấp đầy đủ và số chu kì hô hấp trong một phút của người đó.",
    "",
    "## 1. ĐỊNH NGHĨA HÀM SỐ LƯỢNG GIÁC",
    "**HĐ1.** Hoàn thành bảng sau:",
    "",
    "| $x$ | $\\sin x$ | $\\cos x$ | $\\tan x$ | $\\cot x$ |",
    "| :---: | :---: | :---: | :---: | :---: |",
    "| $\\frac{\\pi}{6}$ | ? | ? | ? | ? |",
    "| $0$ | ? | ? | ? | ? |",
    "| $-\\frac{\\pi}{2}$ | ? | ? | ? | ? |",
    "",
    "Với mỗi số thực $x$, ta xác định được duy nhất một điểm $M$ trên đường tròn lượng giác sao cho số đo của góc lượng giác $(OA, OM)$ bằng $x$. Do đó, ta luôn xác định được các giá trị lượng giác $\\sin x$ và $\\cos x$ của $x$ lần lượt là tung độ và hoành độ của điểm $M$. Nếu $\\cos x \\neq 0$, ta định nghĩa $\\tan x = \\frac{\\sin x}{\\cos x}$ và nếu $\\sin x \\neq 0$, ta định nghĩa $\\cot x = \\frac{\\cos x}{\\sin x}$.",
    "",
    "[Hình ảnh: Đường tròn lượng giác tâm O. Một điểm M nằm trên đường tròn phần tư thứ nhất tạo với trục Ox góc lượng giác x. Hình chiếu của M lên Ox là H, lên Oy là K. OA là tia đầu trùng Ox, OB là trục Oy.]",
    "",
    "22",
    "Từ đây, ta có định nghĩa sau về các hàm số lượng giác.",
    "",
    "| |",
    "| :--- |",
    "| • Quy tắc đặt tương ứng mỗi số thực $x$ với số thực $\\sin x$ được gọi là **hàm số sin**, kí hiệu là $y = \\sin x$.<br>Tập xác định của hàm số sin là $\\mathbb{R}$.<br>• Quy tắc đặt tương ứng mỗi số thực $x$ với số thực $\\cos x$ được gọi là **hàm số côsin**, kí hiệu là $y = \\cos x$.<br>Tập xác định của hàm số côsin là $\\mathbb{R}$.<br>• Hàm số cho bằng công thức $y = \\frac{\\sin x}{\\cos x}$ được gọi là **hàm số tang**, kí hiệu là $y = \\tan x$.<br>Tập xác định của hàm số tang là $\\mathbb{R} \\setminus \\left\\{\\frac{\\pi}{2} + k\\pi \\mid k \\in \\mathbb{Z}\\right\\}$.<br>• Hàm số cho bằng công thức $y = \\frac{\\cos x}{\\sin x}$ được gọi là **hàm số côtang**, kí hiệu là $y = \\cot x$.<br>Tập xác định của hàm số côtang là $\\mathbb{R} \\setminus \\{k\\pi \\mid k \\in \\mathbb{Z}\\}$. |",
    "",
    "**Ví dụ 1.** Tìm tập xác định của hàm số $y = \\frac{1}{\\cos x}$.",
    "**Giải**",
    "Biểu thức $\\frac{1}{\\cos x}$ có nghĩa khi $\\cos x \\neq 0$, tức là $x \\neq \\frac{\\pi}{2} + k\\pi \\, (k \\in \\mathbb{Z})$.",
    "Vậy tập xác định của hàm số đã cho là $\\mathbb{R} \\setminus \\left\\{\\frac{\\pi}{2} + k\\pi \\mid k \\in \\mathbb{Z}\\right\\}$.",
    "",
    "**Luyện tập 1.** Tìm tập xác định của hàm số $y = \\frac{1}{\\sin x}$.",
    "",
    "## 2. HÀM SỐ CHẴN, HÀM SỐ LẺ, HÀM SỐ TUẦN HOÀN",
    "",
    "### a) Hàm số chẵn, hàm số lẻ",
    "**HĐ2.** Cho hai hàm số $f(x) = x^2$ và $g(x) = x^3$, với các đồ thị như hình dưới đây.",
    "",
    "[Hình ảnh: Đồ thị hàm số $y = f(x) = x^2$, là một parabol đi qua gốc toạ độ, nhận trục Oy làm trục đối xứng.]",
    "*Đồ thị hàm số $y = f(x) = x^2$*",
    "",
    "[Hình ảnh: Đồ thị hàm số $y = g(x) = x^3$, là đường cong bậc 3 đi qua gốc toạ độ, nhận gốc toạ độ làm tâm đối xứng.]",
    "*Đồ thị hàm số $y = g(x) = x^3$*",
    "",
    "23",
    "a) Tìm các tập xác định $D_f, D_g$ của các hàm số $f(x)$ và $g(x)$.",
    "b) Chứng tỏ rằng $f(-x) = f(x), \\forall x \\in D_f$. Có nhận xét gì về tính đối xứng của đồ thị hàm số $y = f(x)$ đối với hệ trục toạ độ $Oxy$?",
    "c) Chứng tỏ rằng $g(-x) = -g(x), \\forall x \\in D_g$. Có nhận xét gì về tính đối xứng của đồ thị hàm số $y = g(x)$ đối với hệ trục toạ độ $Oxy$?",
    "",
    "| Cho hàm số $y = f(x)$ có tập xác định là $D$. |",
    "| :--- |",
    "| • Hàm số $f(x)$ được gọi là **hàm số chẵn** nếu $\\forall x \\in D$ thì $-x \\in D$ và $f(-x) = f(x)$.<br>Đồ thị của một hàm số chẵn nhận trục tung là trục đối xứng.<br>• Hàm số $f(x)$ được gọi là **hàm số lẻ** nếu $\\forall x \\in D$ thì $-x \\in D$ và $f(-x) = -f(x)$.<br>Đồ thị của một hàm số lẻ nhận gốc toạ độ là tâm đối xứng. |",
    "",
    "**Nhận xét.** Để vẽ đồ thị của một hàm số chẵn (tương ứng, lẻ), ta chỉ cần vẽ phần đồ thị của hàm số nằm ở bên phải trục tung, sau đó lấy đối xứng phần đồ thị đã vẽ qua trục tung (tương ứng, qua gốc toạ độ), ta sẽ được đồ thị của hàm số đã cho.",
    "",
    "**Ví dụ 2.** Xét tính chẵn, lẻ của hàm số $f(x) = x\\sin x$.",
    "**Giải**",
    "Tập xác định của hàm số là $D = \\mathbb{R}$.",
    "Do đó, nếu $x$ thuộc tập xác định $D$ thì $-x$ cũng thuộc tập xác định $D$.",
    "Ta có: $f(-x) = (-x)\\sin(-x) = x\\sin x = f(x), \\forall x \\in D$.",
    "Vậy $f(x) = x\\sin x$ là hàm số chẵn.",
    "",
    "**Luyện tập 2.** Xét tính chẵn, lẻ của hàm số $g(x) = \\frac{1}{x}$.",
    "",
    "### b) Hàm số tuần hoàn",
    "**HĐ3.** So sánh:",
    "a) $\\sin(x + 2\\pi)$ và $\\sin x$; \\qquad b) $\\cos(x + 2\\pi)$ và $\\cos x$;",
    "c) $\\tan(x + \\pi)$ và $\\tan x$; \\qquad d) $\\cot(x + \\pi)$ và $\\cot x$.",
    "",
    "| Hàm số $y = f(x)$ có tập xác định $D$ được gọi là **hàm số tuần hoàn** nếu tồn tại số $T \\neq 0$ sao cho với mọi $x \\in D$ ta có: |",
    "| :--- |",
    "| i) $x + T \\in D$ và $x - T \\in D$;<br>ii) $f(x + T) = f(x)$.<br>Số $T$ dương nhỏ nhất thoả mãn các điều kiện trên (nếu có) được gọi là **chu kì** của hàm số tuần hoàn đó. |",
    "",
    "[?] Hàm số hằng $f(x) = c$ ($c$ là hằng số) có phải là hàm số tuần hoàn không? Nếu hàm số tuần hoàn thì nó có chu kì không?",
    "",
    "24",
    "**Nhận xét**",
    "a) Các hàm số $y = \\sin x$ và $y = \\cos x$ tuần hoàn với chu kì $2\\pi$. Các hàm số $y = \\tan x$ và $y = \\cot x$ tuần hoàn với chu kì $\\pi$.",
    "b) Để vẽ đồ thị của một hàm số tuần hoàn với chu kì $T$, ta chỉ cần vẽ đồ thị của hàm số này trên đoạn $[a; a + T]$, sau đó dịch chuyển song song với trục hoành phần đồ thị đã vẽ sang phải và sang trái các đoạn có độ dài lần lượt là $T, 2T, 3T, \\dots$ ta được toàn bộ đồ thị của hàm số.",
    "",
    "**Ví dụ 3.** Xét tính tuần hoàn của hàm số $y = \\sin 2x$.",
    "**Giải**",
    "Hàm số có tập xác định là $\\mathbb{R}$ và với mọi số thực $x$, ta có:",
    "$x - \\pi \\in \\mathbb{R}, x + \\pi \\in \\mathbb{R}$,",
    "$\\sin 2(x + \\pi) = \\sin(2x + 2\\pi) = \\sin 2x$.",
    "Vậy $y = \\sin 2x$ là hàm số tuần hoàn.",
    "**Chú ý.** Tổng quát, người ta chứng minh được các hàm số $y = A\\sin \\omega x$ và $y = A\\cos \\omega x$ ($\\omega \\neq 0$) là những hàm số tuần hoàn với chu kì $T = \\frac{2\\pi}{|\\omega|}$.",
    "",
    "**Luyện tập 3.** Xét tính tuần hoàn của hàm số $y = \\tan 2x$.",
    "",
    "## 3. ĐỒ THỊ VÀ TÍNH CHẤT CỦA HÀM SỐ $y = \\sin x$",
    "**HĐ4.** Cho hàm số $y = \\sin x$.",
    "a) Xét tính chẵn, lẻ của hàm số.",
    "b) Hoàn thành bảng giá trị sau của hàm số $y = \\sin x$ trên đoạn $[-\\pi; \\pi]$ bằng cách tính giá trị của $\\sin x$ với những $x$ không âm, sau đó sử dụng kết quả câu a để suy ra giá trị tương ứng của $\\sin x$ với những $x$ âm.",
    "",
    "| $x$ | $-\\pi$ | $-\\frac{3\\pi}{4}$ | $-\\frac{\\pi}{2}$ | $-\\frac{\\pi}{4}$ | $0$ | $\\frac{\\pi}{4}$ | $\\frac{\\pi}{2}$ | $\\frac{3\\pi}{4}$ | $\\pi$ |",
    "| :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: |",
    "| $y = \\sin x$ | ? | ? | ? | ? | ? | ? | ? | ? | ? |",
    "",
    "Bằng cách lấy nhiều điểm $M(x; \\sin x)$ với $x \\in [-\\pi; \\pi]$ và nối lại ta được đồ thị hàm số $y = \\sin x$ trên đoạn $[-\\pi; \\pi]$.",
    "c) Bằng cách làm tương tự câu b cho các đoạn khác có độ dài bằng chu kì $T = 2\\pi$, ta được đồ thị của hàm số $y = \\sin x$ như hình dưới đây.",
    "",
    "[Hình ảnh: Đồ thị hàm số $y = \\sin x$ là một đường hình sin lượn sóng đi qua gốc toạ độ O. Trục hoành đánh dấu các điểm $-\\frac{5\\pi}{2}, -2\\pi, -\\frac{3\\pi}{2}, -\\pi, -\\frac{\\pi}{2}, 0, \\frac{\\pi}{2}, \\pi, \\frac{3\\pi}{2}, 2\\pi, \\frac{5\\pi}{2}$. Các giá trị lớn nhất là 1 và nhỏ nhất là -1.]",
    "*Hình 1.14*",
    "",
    "25",
    "Từ đồ thị ở Hình 1.14, hãy cho biết tập giá trị, các khoảng đồng biến, các khoảng nghịch biến của hàm số $y = \\sin x$.",
    "",
    "| Hàm số $y = \\sin x$: |",
    "| :--- |",
    "| • Có tập xác định là $\\mathbb{R}$ và tập giá trị là $[-1; 1]$; |",
    "| • Là hàm số lẻ và tuần hoàn với chu kì $2\\pi$; |",
    "| • Đồng biến trên mỗi khoảng $\\left(-\\frac{\\pi}{2} + k2\\pi; \\frac{\\pi}{2} + k2\\pi\\right)$ và nghịch biến trên mỗi khoảng $\\left(\\frac{\\pi}{2} + k2\\pi; \\frac{3\\pi}{2} + k2\\pi\\right), k \\in \\mathbb{Z}$; |",
    "| • Có đồ thị đối xứng qua gốc toạ độ và gọi là một **đường hình sin**. |",
    "",
    "**Ví dụ 4.** Sử dụng đồ thị ở Hình 1.14, hãy xác định các giá trị của $x$ trên đoạn $\\left[-\\frac{\\pi}{2}; \\frac{3\\pi}{2}\\right]$ để hàm số $y = \\sin x$:",
    "a) Nhận giá trị bằng 0; \\qquad b) Nhận giá trị dương.",
    "**Giải**",
    "a) Từ đồ thị ta suy ra trên đoạn $\\left[-\\frac{\\pi}{2}; \\frac{3\\pi}{2}\\right]$, $y = 0$ khi $x = 0; x = \\pi$.",
    "b) Hàm số nhận giá trị dương ứng với phần đồ thị nằm trên trục hoành. Từ đồ thị ta suy ra trên đoạn $\\left[-\\frac{\\pi}{2}; \\frac{3\\pi}{2}\\right]$, thì $y > 0$ khi $x \\in (0; \\pi)$.",
    "",
    "**Luyện tập 4.** Tìm tập giá trị của hàm số $y = 2\\sin x$.",
    "",
    "**Vận dụng 1.** Xét tình huống mở đầu.",
    "a) Giải bài toán ở *tình huống mở đầu*.",
    "b) Biết rằng quá trình hít vào xảy ra khi $v > 0$ và quá trình thở ra xảy ra khi $v < 0$.",
    "Trong khoảng thời gian từ $0$ đến $5$ giây, khoảng thời điểm nào thì người đó hít vào? người đó thở ra?",
    "",
    "## 4. ĐỒ THỊ VÀ TÍNH CHẤT CỦA HÀM SỐ $y = \\cos x$",
    "**HĐ5.** Cho hàm số $y = \\cos x$.",
    "a) Xét tính chẵn, lẻ của hàm số.",
