INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN11_T1')), 'B10', 'Đường thẳng và mặt phẳng trong không gian', 70, 1, $JSON$
{
  "content": [
    "# CHƯƠNG IV",
    "# QUAN HỆ SONG SONG TRONG KHÔNG GIAN",
    "",
    "Ở các lớp dưới, ta đã học về Hình học phẳng, môn học nghiên cứu tính chất của các hình trong mặt phẳng như hình tam giác, hình tứ giác, hình tròn,... Tuy nhiên, các vật thể thường gặp trong thực tế đời sống như hộp phấn, cục tẩy, chặn giấy là các hình trong không gian. Một số tính chất của những hình này đã được giới thiệu và thừa nhận trong phần Hình học trực quan. Trong chương này, ta sẽ tiếp tục học về Hình học không gian, môn học nghiên cứu tính chất của các hình trong không gian dựa trên các lập luận toán học logic và chặt chẽ. Nội dung chính của chương liên quan đến đường thẳng, mặt phẳng trong không gian và vị trí tương đối giữa chúng.",
    "",
    "[Hình ảnh: Bản vẽ kĩ thuật 2D. Máy in 3D đang in một mô hình nhà. Một người đang xem mô hình 3D của một chiếc ô tô trên máy tính.]",
    "*Hình học không gian đóng vai trò quan trọng trong xây dựng và đồ hoạ như vẽ kĩ thuật, in 3D, thiết kế với sự hỗ trợ của máy tính CAD (Computer Aided Design).*",
    "",
    "# Bài 10. ĐƯỜNG THẲNG VÀ MẶT PHẲNG TRONG KHÔNG GIAN",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Mặt phẳng<br>• Điểm thuộc mặt phẳng<br>• Các điểm đồng phẳng<br>• Giao tuyến của hai mặt phẳng<br>• Hình chóp và hình tứ diện | • Nhận biết các quan hệ liên thuộc cơ bản giữa điểm, đường thẳng, mặt phẳng trong không gian.<br>• Mô tả ba cách xác định mặt phẳng.<br>• Xác định giao tuyến của hai mặt phẳng, giao điểm của đường thẳng và mặt phẳng.<br>• Nhận biết hình chóp và hình tứ diện.<br>• Mô tả một số hình ảnh trong thực tiễn có liên quan đến đường thẳng, mặt phẳng trong không gian. |",
    "",
    "Điểm, đường thẳng và mối quan hệ liên thuộc giữa hai đối tượng hình học này đã được giới thiệu trong Hình học phẳng. Bài này tiếp tục trình bày một đối tượng hình học khác là mặt phẳng, đồng thời nghiên cứu mối quan hệ liên thuộc giữa điểm, đường thẳng với mặt phẳng.",
    "",
    "70",
    "## 1. KHÁI NIỆM MỞ ĐẦU",
    "Mặt bảng, màn hình máy tính hay mặt nước lúc tĩnh lặng là một số hình ảnh về một phần của mặt phẳng. Mặt phẳng không có bề dày và không có giới hạn.",
    "",
    "[Hình ảnh: Một cái bảng đen, một chiếc laptop mở màn hình, và mặt biển lúc hoàng hôn tĩnh lặng.]",
    "",
    "**Chú ý**",
    "- Để biểu diễn mặt phẳng ta thường dùng một hình bình hành và viết tên của mặt phẳng vào một góc của hình. Ta cũng có thể sử dụng một góc và viết tên của mặt phẳng ở bên trong góc đó.",
    "",
    "[Hình ảnh: Hai cách biểu diễn mặt phẳng bằng hình vẽ. Hình thứ nhất là một hình bình hành có chữ P ở góc. Hình thứ hai là một góc tạo bởi hai tia, có chữ $\\alpha$ ở trong góc.]",
    "*Hình 4.1*",
    "",
    "- Để kí hiệu mặt phẳng ta dùng chữ cái in hoa hoặc chữ cái Hy Lạp đặt trong dấu ngoặc ( ). Trong Hình 4.1, ta có mặt phẳng $(P)$ và mặt phẳng $(\\alpha)$.",
    "",
