    "| • Một mặt phẳng được hoàn toàn xác định khi biết nó đi qua một điểm và chứa một đường thẳng không đi qua điểm đó.<br>• Một mặt phẳng được hoàn toàn xác định khi biết nó chứa hai đường thẳng cắt nhau. |",
