    "74",
    "**Chú ý.** Mặt phẳng được xác định bởi điểm $A$ và đường thẳng $d$ không chứa $A$ được kí hiệu là $\\text{mp}(A, d)$. Mặt phẳng được xác định bởi hai đường thẳng cắt nhau $a$ và $b$ được kí hiệu là $\\text{mp}(a, b)$.",
    "",
    "**Ví dụ 4.** Cho hai đường thẳng cắt nhau $a, b$ và gọi $S$ là một điểm không thuộc $\\text{mp}(a, b)$ (H.4.10). Xác định giao tuyến của $\\text{mp}(S, a)$ và $\\text{mp}(S, b)$.",
    "",
    "[Hình ảnh: Điểm S không thuộc mặt phẳng (a, b). Giao tuyến của mp(S, a) và mp(S, b) là đường thẳng SM, với M là giao điểm của a và b.]",
