    "",
    "**Luyện tập 4.** Trong Ví dụ 4, vẽ một đường thẳng $c$ cắt cả hai đường thẳng $a$ và $b$. Xác định giao tuyến của hai mặt phẳng: $\\text{mp}(S, a)$ và $\\text{mp}(S, c); \\text{mp}(S, b)$ và $\\text{mp}(S, c)$.",
    "",
    "**Vận dụng 2.** Để tránh cho cửa ra vào không bị va đập vào các đồ dùng xung quanh (do mở cửa quá mạnh hoặc do gió to dập cửa), người ta thường sử dụng một phụ kiện là hít cửa nam châm. Hãy giải thích tại sao khi cửa được hút tới vị trí của nam châm thì cánh cửa được giữ cố định.",
    "",
    "[Hình ảnh: Cánh cửa và một cục hít nam châm gắn trên sàn.]",
    "",
    "## 4. HÌNH CHÓP VÀ HÌNH TỨ DIỆN",
    "**HĐ7.** Các hình ảnh dưới đây có đặc điểm chung nào với hình chóp tam giác đều mà em đã học ở lớp 8?",
    "",
    "[Hình ảnh: Kim tự tháp Ai Cập, một chiếc ô hình chóp tứ giác, một khối rubik hình tứ diện đều.]",
    "",
    "| |",
    "| :--- |",
    "| • Cho đa giác lồi $A_1A_2 \\dots A_n$ và một điểm $S$ nằm ngoài mặt phẳng chứa đa giác đó. Nối $S$ với các đỉnh $A_1, A_2, \\dots, A_n$ để được $n$ tam giác $SA_1A_2, SA_2A_3, \\dots, SA_nA_1$. Hình gồm $n$ tam giác $SA_1A_2, SA_2A_3, \\dots, SA_nA_1$ và đa giác $A_1A_2 \\dots A_n$ được gọi là **hình chóp** và kí hiệu là $S.A_1A_2 \\dots A_n$.<br>• Trong hình chóp $S.A_1A_2 \\dots A_n$, điểm $S$ được gọi là đỉnh và đa giác $A_1A_2 \\dots A_n$ được gọi là *mặt đáy*; các tam giác $SA_1A_2, SA_2A_3, \\dots, SA_nA_1$ được gọi là các *mặt bên*; các cạnh $SA_1, SA_2, \\dots, SA_n$ được gọi là các *cạnh bên*; các cạnh $A_1A_2, A_2A_3, \\dots, A_nA_1$ được gọi là các *cạnh đáy*. |",
    "",
    "**Chú ý**",
    "Tên của hình chóp được gọi dựa theo tên của đa giác đáy, ví dụ hình chóp có đáy là tứ giác được gọi là hình chóp tứ giác.",
    "",
    "75",
    "**Ví dụ 5.** Cho hình chóp $S.ABCD$ (H.4.11). Hình chóp đó có bao nhiêu cạnh?",
    "**Giải**",
    "Hình chóp $S.ABCD$ có 8 cạnh là $SA, SB, SC, SD, AB, BC, CD, DA$.",
    "",
    "[Hình ảnh: Hình chóp tứ giác S.ABCD. ABCD là tứ giác lồi.]",
    "*Hình 4.11*",
    "",
    "**Luyện tập 5.** Cho hình chóp $S.ABCD$. Gọi tên các mặt bên và mặt đáy của hình chóp đó.",
    "",
    "**HĐ8.** Trong các hình chóp ở HĐ7, hình chóp nào có ít mặt nhất? Xác định số cạnh và số mặt của hình chóp đó.",
    "",
    "| |",
    "| :--- |",
    "| • Cho bốn điểm $A, B, C, D$ không đồng phẳng. Hình gồm bốn tam giác $ABC, ACD, ABD$ và $BCD$ được gọi là **hình tứ diện** và được kí hiệu là $ABCD$.<br>• Trong hình tứ diện $ABCD$, các điểm $A, B, C, D$ được gọi là các *đỉnh* của tứ diện, các đoạn thẳng $AB, BC, CD, DA, AC, BD$ được gọi là các *cạnh* của tứ diện, các tam giác $ABC, ACD, ABD, BCD$ được gọi là các *mặt* của tứ diện.<br>• Trong hình tứ diện, hai cạnh không có đỉnh chung được gọi là *hai cạnh đối diện*, đỉnh không nằm trên một mặt được gọi là *đỉnh đối diện* với mặt đó. |",
    "",
    "[Khung chữ bên lề: Hình ảnh bạn rô-bốt nhỏ. \"Hình tứ diện có bốn mặt là các tam giác đều gọi là hình tứ diện đều.\"]",
    "",
    "**Nhận xét.** Hình tứ diện là một hình chóp tam giác mà mặt nào của hình tứ diện cũng có thể được coi là mặt đáy.",
    "",
    "**Ví dụ 6.** Cho hình tứ diện $ABCD$ và $E$ là một điểm nằm trong tam giác $BCD$. Gọi $F$ là một điểm nằm giữa $A$ và $E$ (H.4.12). Xác định giao điểm của đường thẳng $BF$ và mặt phẳng $(ACD)$.",
    "",
    "[Hình ảnh: Tứ diện ABCD. Điểm E thuộc tam giác BCD. Điểm F nằm trên đoạn AE. Đường thẳng BF cắt mặt phẳng (ACD) tại N.]",
    "*Hình 4.12*",
    "",
    "**Giải**",
    "Vì điểm $E$ nằm trong tam giác $BCD$ nên đường thẳng $BE$ cắt cạnh $CD$ tại một điểm $M$. Các điểm $A, E$ thuộc mặt phẳng $(ABM)$ nên đường thẳng $AE$ thuộc mặt phẳng $(ABM)$, do đó điểm $F$ thuộc mặt phẳng $(ABM)$. Như vậy các điểm $A, B, E, F, M$ cùng thuộc mặt phẳng $(ABM)$.",
    "Trong tam giác $ABM$, đường thẳng $BF$ cắt $AM$ tại $N$. Vì $N$ thuộc $AM$ và $A, M$ cùng thuộc mặt phẳng $(ACD)$ nên $N$ thuộc mặt phẳng $(ACD)$. Vậy $N$ là giao điểm của đường thẳng $BF$ và mặt phẳng $(ACD)$.",
    "",
    "[Khung chữ bên lề: \"Để xác định giao điểm của một đường thẳng và một mặt phẳng, ta có thể tìm giao điểm của đường thẳng đó với một đường thẳng nằm trong mặt phẳng đã cho.\"]",
    "",
    "**Luyện tập 6.** Trong Ví dụ 6, xác định giao điểm của đường thẳng $DF$ và mặt phẳng $(ABC)$.",
    "",
    "76",
    "# BÀI TẬP",
    "",
    "**4.1.** Trong không gian, cho hai đường thẳng $a, b$ và mặt phẳng $(P)$. Những mệnh đề nào sau đây là đúng?",
    "a) Nếu $a$ chứa một điểm nằm trong $(P)$ thì $a$ nằm trong $(P)$.",
    "b) Nếu $a$ chứa hai điểm phân biệt thuộc $(P)$ thì $a$ nằm trong $(P)$.",
    "c) Nếu $a$ và $b$ cùng nằm trong $(P)$ thì giao điểm (nếu có) của $a$ và $b$ cũng nằm trong $(P)$.",
    "d) Nếu $a$ nằm trong $(P)$ và $a$ cắt $b$ thì $b$ nằm trong $(P)$.",
    "",
    "**4.2.** Cho tam giác $ABC$ và điểm $S$ không thuộc mặt phẳng $(ABC)$. Lấy $D, E$ là các điểm lần lượt thuộc các cạnh $SA, SB$ và $D, E$ khác $S$.",
    "a) Đường thẳng $DE$ có nằm trong mặt phẳng $(SAB)$ không?",
    "b) Giả sử $DE$ cắt $AB$ tại $F$. Chứng minh rằng $F$ là điểm chung của hai mặt phẳng $(SAB)$ và $(CDE)$.",
    "",
    "**4.3.** Cho mặt phẳng $(P)$ và hai đường thẳng $a, b$ nằm trong $(P)$. Một đường thẳng $c$ cắt hai đường thẳng $a$ và $b$ tại hai điểm phân biệt. Chứng minh rằng đường thẳng $c$ nằm trong mặt phẳng $(P)$.",
    "",
    "**4.4.** Cho hình chóp tứ giác $S.ABCD$ và $M$ là một điểm thuộc cạnh $SC$ ($M$ khác $S, C$). Giả sử hai đường thẳng $AB$ và $CD$ cắt nhau tại $N$. Chứng minh rằng đường thẳng $MN$ là giao tuyến của hai mặt phẳng $(ABM)$ và $(SCD)$.",
    "",
    "**4.5.** Cho hình chóp tứ giác $S.ABCD$ và lấy một điểm $E$ thuộc cạnh $SA$ của hình chóp ($E$ khác $S, A$). Trong mặt phẳng $(ABCD)$ vẽ một đường thẳng $d$ cắt các cạnh $CB, CD$ lần lượt tại $M, N$ và cắt các tia $AB, AD$ lần lượt tại $P, Q$.",
    "a) Xác định giao điểm của $\\text{mp}(E, d)$ với các cạnh $SB, SD$ của hình chóp.",
    "b) Xác định giao tuyến của $\\text{mp}(E, d)$ với các mặt của hình chóp.",
    "",
    "**4.6.** Cho hình tứ diện $ABCD$. Trên các cạnh $AC, BC, BD$ lần lượt lấy các điểm $M, N, P$ sao cho $AM = CM, BN = CN, BP = 2DP$.",
    "a) Xác định giao điểm của đường thẳng $CD$ và mặt phẳng $(MNP)$.",
    "b) Xác định giao tuyến của hai mặt phẳng $(ACD)$ và $(MNP)$.",
    "",
    "**4.7.** Tại các nhà hàng, khách sạn, nhân viên phục vụ bàn thường xuyên phải bưng bê nhiều khay, đĩa đồ ăn khác nhau. Một trong những nguyên tắc nhân viên cần nhớ là khay phải được bưng bằng ít nhất 3 ngón tay. Hãy giải thích tại sao.",
    "",
    "[Hình ảnh: Một người phục vụ đang bưng một cái khay bằng một tay, xoè các ngón tay ra.]",
    "",
    "**4.8.** Bàn cắt giấy là một dụng cụ được sử dụng thường xuyên ở các cửa hàng photo-copy. Bàn cắt giấy gồm hai phần chính: phần bàn hình chữ nhật có chia kích thước giấy và phần dao cắt có một đầu được cố định vào bàn. Hãy giải thích tại sao khi sử dụng bàn cắt giấy thì các đường cắt luôn là đường thẳng.",
    "",
    "[Hình ảnh: Một cái bàn cắt giấy kiểu dập xuống.]",
    "",
    "77"
  ]
}
