{
  "content": [
    "# Bài 11. HAI ĐƯỜNG THẲNG SONG SONG",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Hai đường thẳng đồng phẳng<br>• Hai đường thẳng chéo nhau | • Nhận biết vị trí tương đối của hai đường thẳng trong không gian: hai đường thẳng trùng nhau, song song, cắt nhau, chéo nhau.<br>• Giải thích tính chất cơ bản của hai đường thẳng song song trong không gian.<br>• Vận dụng kiến thức về hai đường thẳng song song để mô tả một số hình ảnh trong thực tiễn. |",
    "",
    "Để giải quyết vấn đề tắc đường ở các thành phố lớn, có rất nhiều giải pháp được đưa ra. Trong đó giải pháp xây dựng các hệ thống cầu vượt, đường hoặc đường sắt trên cao đã và đang được đưa vào thực tế ở Việt Nam. Toán học mô tả vị trí tương quan giữa các tuyến đường trên như thế nào?",
    "",
    "[Hình ảnh: Hệ thống giao thông phức tạp ở một nút giao, gồm các tuyến đường bộ ở các tầng khác nhau và đường sắt trên cao.]",
    "*Hình 4.13. Tuyến đường bộ (1, 2), tuyến đường vành đai trên cao (3), tuyến đường sắt trên cao (4)*",
    "",
    "## 1. VỊ TRÍ TƯƠNG ĐỐI CỦA HAI ĐƯỜNG THẲNG",
    "**HĐ1.** Hình 4.13 minh hoạ bốn tuyến đường (được coi là thẳng) tại một nút giao ở Hà Nội. Quan sát hình ảnh đó và trả lời các câu hỏi sau:",
    "a) Hai tuyến đường nào giao nhau?",
    "b) Hai tuyến đường nào không giao nhau?",
