    "",
    "| |",
    "| :--- |",
    "| Cho hai đường thẳng $a$ và $b$ trong không gian.<br>• Nếu $a$ và $b$ cùng nằm trong một mặt phẳng thì ta nói $a$ và $b$ **đồng phẳng**. Khi đó, $a$ và $b$ có thể cắt nhau, song song với nhau hoặc trùng nhau.<br>• Nếu $a$ và $b$ không cùng nằm trong bất kì mặt phẳng nào thì ta nói $a$ và $b$ **chéo nhau**. Khi đó, ta cũng nói $a$ chéo với $b$, hoặc $b$ chéo với $a$. |",
    "",
    "[Hình ảnh: Các trường hợp vị trí tương đối của hai đường thẳng a và b. ",
    "1) a cắt b tại M trong mặt phẳng alpha. Kí hiệu $a \\cap b = \\{M\\}$.",
