    "3) a trùng với b trong mặt phẳng alpha. Kí hiệu $a \\equiv b$.",
    "4) a và b chéo nhau. Đường thẳng a cắt mặt phẳng chứa b, không đồng phẳng với b.]",
    "*$a \\cap b = \\{M\\}$; $a$ cắt $b$ tại $M$ | $a // b$; $a$ song song với $b$ | $a \\equiv b$; $a$ trùng với $b$ | $a$ và $b$ chéo nhau*",
    "*Hình 4.14 | Hình 4.15*",
