    "",
    "**Vận dụng 1.** Một chiếc gậy được đặt một đầu dựa vào tường và đầu kia trên mặt sàn (H.4.20). Hỏi có thể đặt chiếc gậy đó song song với một trong các mép tường hay không?",
    "",
    "[Hình ảnh: Một chiếc gậy dài đặt dựa vào góc một căn phòng.]",
    "*Hình 4.20*",
    "",
    "## 2. TÍNH CHẤT CỦA HAI ĐƯỜNG THẲNG SONG SONG",
    "**HĐ2.** Trong không gian, cho một đường thẳng $d$ và một điểm $M$ không nằm trên $d$ (H.4.21). Gọi $(P)$ là mặt phẳng chứa $M$ và $d$.",
