    "",
    "[Khung chữ bên lề: Hình ảnh một rô-bốt nhỏ. \"Các tia sáng Mặt Trời ở gần Trái Đất được coi như các đường thẳng đôi một song song với nhau.\"]",
    "",
    "80",
    "**Ví dụ 3.** Cho tứ diện $ABCD$. Gọi $M, N, P, Q, R, S$ lần lượt là trung điểm của các đoạn thẳng $AB, CD, AD, BC, AC, BD$ (H.4.22).",
