    "[Khung chữ bên lề: Hình ảnh bạn nữ. \"Nếu hai đường thẳng $b$ và $c$ cắt nhau tại $N$ thì ta có thể sử dụng lại kết quả ở câu a.\"]",
    "",
    "[Hình ảnh: Hai hình vẽ về ba mặt phẳng cắt nhau. Hình 4.23: Ba mặt phẳng cắt nhau tạo thành ba giao tuyến đồng quy tại M. Hình 4.24: Ba mặt phẳng cắt nhau tạo thành ba giao tuyến song song với nhau.]",
    "*Hình 4.23 | Hình 4.24*",
    "",
    "Kết quả sau đây còn được biết đến với tên gọi \"Định lí về ba đường giao tuyến\".",
    "",
    "| |",
    "| :--- |",
    "| Nếu ba mặt phẳng đôi một cắt nhau theo ba giao tuyến phân biệt thì ba giao tuyến đó đồng quy hoặc đôi một song song với nhau. |",
    "",
    "**Chú ý.** Từ kết quả trên có thể suy ra rằng: Nếu hai mặt phẳng chứa hai đường thẳng song song với nhau thì giao tuyến của chúng (nếu có) song song với hai đường thẳng đó hoặc trùng với một trong hai đường thẳng đó.",
    "",
    "81",
    "**Ví dụ 4.** Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình bình hành (H.4.25). Xác định giao tuyến của hai mặt phẳng $(SAB)$ và $(SCD)$.",
    "**Giải**",
    "Hai mặt phẳng $(SAB)$ và $(SCD)$ có điểm chung $S$ và chứa hai đường thẳng song song là $AB$ và $CD$. Do đó, giao tuyến của hai mặt phẳng $(SAB)$ và $(SCD)$ là đường thẳng $m$ đi qua $S$ và song song với $AB, CD$.",
    "",
    "[Hình ảnh: Hình chóp S.ABCD, đáy là hình bình hành. Qua S kẻ đường thẳng m song song với AB và CD. m là giao tuyến của (SAB) và (SCD).]",
    "*Hình 4.25*",
    "",
    "**Luyện tập 4.** Trong Ví dụ 4, hãy xác định giao tuyến của hai mặt phẳng $(SAD)$ và $(SBC)$.",
    "",
    "**Vận dụng 2.** Một bể kính chứa nước có đáy là hình chữ nhật được đặt nghiêng như Hình 4.26. Giải thích tại sao đường mép nước $AB$ song song với cạnh $CD$ của bể nước.",
    "",
    "[Hình ảnh: Một bể cá hình hộp chữ nhật chứa nước đặt nghiêng. Mép nước tạo thành một hình chữ nhật nằm ngang.]",
    "*Hình 4.26*",
    "",
    "# BÀI TẬP",
    "",
    "**4.9.** Trong không gian, cho ba đường thẳng $a, b, c$. Những mệnh đề nào sau đây là đúng?",
    "a) Nếu $a$ và $b$ không cắt nhau thì $a$ và $b$ song song.",
    "b) Nếu $b$ và $c$ chéo nhau thì $b$ và $c$ không cùng thuộc một mặt phẳng.",
    "c) Nếu $a$ và $b$ cùng song song với $c$ thì $a$ song song với $b$.",
    "d) Nếu $a$ và $b$ cắt nhau, $b$ và $c$ cắt nhau thì $a$ và $c$ cắt nhau.",
    "",
    "**4.10.** Cho hình chóp $S.ABCD$ có đáy là hình bình hành. Trong các cặp đường thẳng sau, cặp đường thẳng nào cắt nhau, cặp đường thẳng nào song song, cặp đường thẳng nào chéo nhau?",
    "a) $AB$ và $CD$;",
    "b) $AC$ và $BD$;",
    "c) $SB$ và $CD$.",
    "",
    "**4.11.** Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình bình hành. Gọi $M, N, P, Q$ lần lượt là trung điểm của các cạnh bên $SA, SB, SC, SD$ (H.4.27). Chứng minh rằng tứ giác $MNPQ$ là hình bình hành.",
    "",
    "[Hình ảnh: Hình chóp S.ABCD đáy hình bình hành. M, N, P, Q là trung điểm các cạnh bên. MNPQ là hình bình hành.]",
    "*Hình 4.27*",
    "",
    "**4.12.** Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình thang ($AB // CD$). Gọi $M, N$ lần lượt là trung điểm của các cạnh $SA, SB$. Chứng minh rằng tứ giác $MNCD$ là hình thang.",
    "",
    "**4.13.** Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình thang ($AB // CD$). Gọi $M$ là trung điểm của đoạn thẳng $SD$ (H.4.28).",
    "a) Xác định giao tuyến của hai mặt phẳng $(MAB)$ và $(SCD)$.",
    "b) Gọi $N$ là giao điểm của đường thẳng $SC$ và mặt phẳng $(MAB)$. Chứng minh rằng $MN$ là đường trung bình của tam giác $SCD$.",
    "",
    "[Hình ảnh: Hình chóp S.ABCD đáy hình thang. M là trung điểm SD. Mặt phẳng (MAB) cắt SC tại N.]",
    "*Hình 4.28*",
    "",
    "82",
    "**4.14.** Cho tứ diện $ABCD$. Gọi $M, N$ lần lượt là trung điểm của các cạnh $BC, CD$ và $P$ là một điểm thuộc cạnh $AC$.",
    "a) Xác định giao tuyến $d$ của hai mặt phẳng $(AMN)$ và $(BPD)$.",
    "b) Chứng minh rằng $d$ song song với $BD$.",
    "",
    "**4.15.** (Đố vui) Khi hai cánh cửa sổ hình chữ nhật được mở, dù ở vị trí nào, thì hai mép ngoài của chúng luôn song song với nhau (H.4.29). Hãy giải thích tại sao.",
    "Nếu hai cánh cửa sổ có dạng hình thang như Hình 4.30 thì có vị trí nào của hai cánh cửa để hai mép ngoài của chúng song song với nhau hay không?",
    "",
    "[Hình ảnh: Hai hình vẽ cửa sổ mở cánh. Hình 4.29: Cửa sổ cánh hình chữ nhật. Hình 4.30: Cửa sổ cánh hình thang.]",
    "*Hình 4.29 | Hình 4.30*",
    "",
    "**Em có biết?**",
    "Trong không gian, cố định một đường thẳng $\\Delta$ thẳng đứng và gọi $d$ là một đường thẳng tuỳ ý. Ta hãy cùng tìm hiểu hình được tạo bởi đường thẳng $d$ khi quay đường thẳng này quanh đường thẳng $\\Delta$ trong không gian. Nếu $d$ song song với $\\Delta$ hoặc $d$ cắt $\\Delta$ thì có thể dễ dàng hình dung được hình tạo ra là mặt trụ hoặc mặt nón (H.4.31).",
    "",
    "[Hình ảnh: Mặt trụ tròn xoay tạo bởi đường sinh d song song với trục Delta. Mặt nón tròn xoay tạo bởi đường sinh d cắt trục Delta tại O.]",
    "*Hình 4.31*",
    "",
    "Còn nếu $d$ và $\\Delta$ chéo nhau thì sao? Trong hầu hết các trường hợp, hình tạo ra được gọi là mặt hypebol (hyperboloid) như trong Hình 4.32. Mặt hypebol có thể được coi như một \"dạng 3D\" của đường hypebol đã được dạy ở lớp 10. Một điều thú vị là nếu mặt hypebol được cắt bởi một mặt phẳng đi qua đường thẳng $\\Delta$ (trục hypebol) thì vết cắt nhận được chính là một đường hypebol (H.4.33).",
    "",
    "[Hình ảnh: Mặt hyperboloid tròn xoay tạo bởi đường thẳng d chéo với trục Delta quay quanh trục Delta. Hình 4.33 là mặt cắt của mặt hyperboloid qua trục Delta tạo thành đường hypebol.]",
    "*Hình 4.32 | Hình 4.33*",
    "",
    "Hình ảnh của mặt hypebol xuất hiện rất nhiều trong xây dựng, kiến trúc, nghệ thuật,... và trong thực tiễn, chúng ta hoàn toàn có thể \"dựng được\" mặt hypebol bằng cách sử dụng các vật dụng đơn giản như nan tre thẳng, que tính hay những chiếc đũa,... Em có thể tìm thấy một cách dựng như vậy trên các trang web tìm kiếm với từ khoá \"hyperboloid\".",
    "",
    "[Hình ảnh: Ba ví dụ thực tế về cấu trúc dạng hyperboloid: một cái bàn/ghế, một bó que đầy màu sắc, và một toà tháp chọc trời ban đêm.]",
    "",
    "83"
  ]
}
