    "[Hình ảnh: Một tấm bìa màu cam đặt ở góc mặt bàn.]",
    "*Hình 4.44*",
    "",
    "89",
    "**Ví dụ 2.** Cho hình chóp $S.ABCD$. Gọi $M, N, P, Q$ lần lượt là trung điểm của các cạnh $SA, SB, SC, SD$ (H.4.45). Chứng minh rằng hai mặt phẳng $(MNP)$ và $(NPQ)$ cùng song song với mặt phẳng $(ABCD)$, từ đó suy ra bốn điểm $M, N, P, Q$ đồng phẳng.",
    "**Giải**",
    "Vì $M, N$ lần lượt là trung điểm của $SA, SB$ nên $MN$ là đường trung bình của tam giác $SAB$. Do đó, $MN // AB$ và suy ra $MN$ song song với mặt phẳng $(ABCD)$. Tương tự, $NP$ cũng song song với mặt phẳng $(ABCD)$. Vậy mặt phẳng $(MNP)$ song song với mặt phẳng $(ABCD)$. Lập luận tương tự ta có mặt phẳng $(NPQ)$ cũng song song với mặt phẳng $(ABCD)$.",
    "Hai mặt phẳng $(MNP)$ và $(NPQ)$ cùng đi qua điểm $N$ và cùng song song với mặt phẳng $(ABCD)$ nên hai mặt phẳng đó trùng nhau, tức là bốn điểm $M, N, P, Q$ đồng phẳng.",
    "",
    "[Hình ảnh: Hình chóp S.ABCD. M, N, P, Q là trung điểm của SA, SB, SC, SD. Mặt phẳng MNPQ song song với đáy ABCD.]",
    "*Hình 4.45*",
    "",
    "**Luyện tập 2.** Cho hình chóp $S.ABCD$. Gọi $M, N, P, Q$ lần lượt là các điểm thuộc các cạnh $SA, SB, SC, SD$ sao cho $\\frac{MA}{MS} = \\frac{NB}{NS} = \\frac{PC}{PS} = \\frac{QD}{QS} = \\frac{1}{2}$. Chứng minh rằng bốn điểm $M, N, P, Q$ đồng phẳng.",
    "",
    "**HĐ4.** Cho hai mặt phẳng song song $(P)$ và $(Q)$. Giả sử mặt phẳng $(R)$ cắt mặt phẳng $(P)$ theo giao tuyến $a$ (H.4.46).",
