    "",
    "| |",
    "| :--- |",
    "| Cho hai mặt phẳng song song. Nếu một mặt phẳng cắt mặt phẳng này thì cũng cắt mặt phẳng kia và hai giao tuyến song song với nhau. |",
    "",
    "[Hình ảnh: Hai mặt phẳng song song (P) và (Q) bị cắt bởi mặt phẳng (R) tạo thành hai giao tuyến song song a và b.]",
    "*Hình 4.46*",
    "",
    "**Ví dụ 3.** Trong Ví dụ 2, gọi $E, F$ lần lượt là các điểm thuộc các cạnh $AB, CD$ (H.4.47). Xác định giao tuyến của mặt phẳng $(MEF)$ và mặt phẳng $(MNPQ)$.",
    "**Giải**",
    "Trong Ví dụ 2, ta đã chứng minh được hai mặt phẳng $(MNPQ)$ và $(ABCD)$ song song với nhau. Vì vậy hai giao tuyến của mặt phẳng $(MEF)$ với hai mặt phẳng $(MNPQ)$ và $(ABCD)$ song song với nhau. Trong mặt phẳng $(MEF)$, qua $M$ vẽ đường thẳng song song với $EF$ cắt $PQ$ tại $G$ thì đường thẳng $MG$ là giao tuyến của hai mặt phẳng $(MEF)$ và $(MNPQ)$.",
    "",
    "[Hình ảnh: Hình chóp S.ABCD có mặt phẳng MNPQ song song với ABCD. E trên AB, F trên CD. Mặt phẳng MEF cắt MNPQ theo giao tuyến MG song song với EF.]",
    "*Hình 4.47*",
    "",
    "90",
    "**Luyện tập 3.** Trong Ví dụ 3, hãy xác định giao tuyến của mặt phẳng $(EMQ)$ và mặt phẳng $(ABCD)$.",
    "",
    "## 3. ĐỊNH LÍ THALÈS TRONG KHÔNG GIAN",
    "**HĐ5.** Cho ba mặt phẳng $(P), (Q)$ và $(R)$ đôi một song song. Hai đường thẳng phân biệt $d$ và $d'$ cắt ba mặt phẳng lần lượt tại $A, B, C$ và $A', B', C'$ ($C$ khác $C'$). Gọi $D$ là giao điểm của $AC'$ và $(Q)$ (H.4.48).",
    "a) Các cặp đường thẳng $BD$ và $CC', B'D$ và $AA'$ có song song với nhau không?",
    "b) Các tỉ số $\\frac{AB}{BC}, \\frac{AD}{DC'}$ và $\\frac{A'B'}{B'C'}$ có bằng nhau không?",
    "",
    "[Hình ảnh: Ba mặt phẳng song song (P), (Q), (R) cắt hai đường thẳng d, d' lần lượt tại A, B, C và A', B', C'. Gọi D là giao điểm của AC' và (Q). (P) qua A, A', (Q) qua B, B', D, (R) qua C, C'.]",
    "*Hình 4.48*",
    "",
    "Kết quả sau còn được biết đến như định lí Thalès trong không gian.",
    "",
    "[Khung chữ bên lề: \"Nhắc lại định lí Thalès trong hình học phẳng.\"]",
    "",
    "| |",
    "| :--- |",
    "| Ba mặt phẳng đôi một song song chắn trên hai cát tuyến phân biệt bất kì những đoạn thẳng tương ứng tỉ lệ. |",
    "",
    "Trong Hình 4.48 ta có $\\frac{AB}{A'B'} = \\frac{BC}{B'C'} = \\frac{AC}{A'C'}$.",
    "",
    "**Ví dụ 4.** Cho hình tứ diện $SABC$. Trên cạnh $SA$ lấy các điểm $A_1, A_2$ sao cho $A_1A = 2A_1A_2$. Gọi $(P)$ và $(Q)$ là hai mặt phẳng song song với mặt phẳng $(ABC)$ và lần lượt đi qua $A_1, A_2$. Mặt phẳng $(P)$ cắt các cạnh $SB, SC$ lần lượt tại $B_1, C_1$. Mặt phẳng $(Q)$ cắt các cạnh $SB, SC$ lần lượt tại $B_2, C_2$ (H.4.49). Chứng minh $B_2B_1 = 2B_1B$ và $C_2C_1 = 2C_1C$.",
    "**Giải**",
    "Áp dụng định lí Thalès cho ba mặt phẳng đôi một song song $(P), (Q), (ABC)$ và hai cát tuyến $SA, SB$, ta có $\\frac{A_2A_1}{A_1A} = \\frac{B_2B_1}{B_1B}$.",
    "Vì $A_2A_1 = 2A_1A$ nên $B_2B_1 = 2B_1B$.",
    "Tương tự với hai cát tuyến $SA, SC$ suy ra $C_2C_1 = 2C_1C$.",
    "",
    "[Hình ảnh: Hình chóp tam giác SABC. Hai mặt phẳng song song với đáy cắt các cạnh bên, tạo ra các điểm A1, B1, C1 và A2, B2, C2.]",
    "*Hình 4.49*",
    "",
    "**Luyện tập 4.** Trong HĐ5, cho $AB = 2 \\text{ cm}, BC = 4 \\text{ cm}$ và $A'B' = 3 \\text{ cm}$. Tính độ dài của đoạn thẳng $B'C'$.",
    "",
    "## 4. HÌNH LĂNG TRỤ VÀ HÌNH HỘP",
    "**HĐ6.** Các hình ảnh dưới đây có đặc điểm chung nào với hình lăng trụ đứng tam giác mà em đã học ở lớp 7?",
    "",
    "[Hình ảnh: Ba hình ảnh: Thanh socola Toblerone hình lăng trụ tam giác, cục tẩy hình hộp chữ nhật (hai màu), khối gỗ nhỏ hình lăng trụ lục giác.]",
    "",
    "91",
    "| |",
    "| :--- |",
    "| Cho hai mặt phẳng song song $(\\alpha)$ và $(\\alpha')$. Trên $(\\alpha)$ cho đa giác lồi $A_1A_2 \\dots A_n$. Qua các đỉnh $A_1, A_2, \\dots, A_n$ vẽ các đường thẳng đôi một song song và cắt mặt phẳng $(\\alpha')$ tại $A'_1, A'_2, \\dots, A'_n$. Hình gồm hai đa giác $A_1A_2 \\dots A_n, A'_1A'_2 \\dots A'_n$ và các tứ giác $A_1A'_1A'_2A_2, A_2A'_2A'_3A_3, \\dots, A_nA'_nA'_1A_1$ được gọi là **hình lăng trụ** và kí hiệu là $A_1A_2 \\dots A_n.A'_1A'_2 \\dots A'_n$ (H.4.50).<br>• Các điểm $A_1, A_2, \\dots, A_n$ và $A'_1, A'_2, \\dots, A'_n$ được gọi là các *đỉnh*, các đoạn thẳng $A_1A'_1, A_2A'_2, \\dots, A_nA'_n$ được gọi là các *cạnh bên*, các đoạn thẳng $A_1A_2, A_2A_3, \\dots, A_nA_1$ và $A'_1A'_2, A'_2A'_3, \\dots, A'_nA'_1$ được gọi là các *cạnh đáy* của hình lăng trụ.<br>• Hai đa giác $A_1A_2 \\dots A_n$ và $A'_1A'_2 \\dots A'_n$ được gọi là hai *mặt đáy* của hình lăng trụ.<br>• Các tứ giác $A_1A'_1A'_2A_2, A_2A'_2A'_3A_3, \\dots, A_nA'_nA'_1A_1$ được gọi là các *mặt bên* của hình lăng trụ. |",
    "",
    "[Hình ảnh: Hình lăng trụ ngũ giác A1A2A3A4A5.A'1A'2A'3A'4A'5 cắt bởi hai mặt phẳng song song alpha và alpha'.]",
    "*Hình 4.50*",
    "",
    "[Khung chữ bên lề: \"Hình lăng trụ có đáy là tam giác được gọi là hình lăng trụ tam giác, hình lăng trụ có đáy là tứ giác được gọi là hình lăng trụ tứ giác.\"]",
    "",
    "**?** Hãy giải thích tại sao các mặt bên của hình lăng trụ là hình bình hành, từ đó suy ra các cạnh bên đôi một song song và có độ dài bằng nhau.",
    "",
    "**Chú ý.** Tên của hình lăng trụ được gọi dựa theo tên của đa giác đáy.",
    "",
    "**Ví dụ 5.** Cho hình lăng trụ tam giác $ABC.A'B'C'$. Một mặt phẳng song song với mặt đáy của hình lăng trụ cắt các cạnh bên của hình lăng trụ lần lượt tại $A'', B'', C''$ (H.4.51). Chứng minh rằng $ABC.A''B''C''$ là hình lăng trụ.",
    "**Giải**",
    "Vì các cạnh bên của hình lăng trụ $ABC.A'B'C'$ đôi một song song nên $AA'', BB'', CC''$ đôi một song song. Mặt phẳng $(ABC)$ song song với mặt phẳng $(A''B''C'')$ nên $ABC.A''B''C''$ là hình lăng trụ.",
    "",
    "[Hình ảnh: Hình lăng trụ tam giác ABC.A'B'C'. Mặt phẳng A''B''C'' cắt ngang lăng trụ và song song với hai đáy.]",
    "*Hình 4.51*",
    "",
    "**Luyện tập 5.** Cho hình lăng trụ tam giác $ABC.A'B'C'$. Gọi $M$ và $M'$ lần lượt là trung điểm của các cạnh $BC$ và $B'C'$. Chứng minh rằng $AMC.A'M'C'$ là hình lăng trụ.",
    "",
    "**HĐ7.** Hình ảnh nào trong HĐ6 gợi nên hình ảnh về hình lăng trụ có đáy là hình bình hành?",
    "",
    "92",
    "| |",
    "| :--- |",
    "| Hình lăng trụ tứ giác $ABCD.A'B'C'D'$ có hai đáy là hình bình hành được gọi là **hình hộp**.<br>– Các cặp điểm $A$ và $C', B$ và $D', C$ và $A', D$ và $B'$ được gọi là các đỉnh đối diện của hình hộp.<br>– Các đoạn thẳng $AC', BD', CA'$ và $DB'$ được gọi là các đường chéo của hình hộp.<br>– Các cặp tứ giác $ABCD$ và $A'B'C'D', ADD'A'$ và $BCC'B', ABB'A'$ và $DCC'D'$ được gọi là hai mặt đối diện của hình hộp. |",
    "",
    "[Khung chữ bên lề: Hình ảnh bạn rô-bốt. \"Hai đỉnh đối diện của hình hộp là hai đỉnh không cùng thuộc bất kì mặt nào của hình hộp. Hai mặt đối diện của hình hộp là hai mặt không có điểm chung.\"]",
    "",
    "**Ví dụ 6.** Cho hình hộp $ABCD.A'B'C'D'$ (H.4.52). Chứng minh rằng các đường chéo $AC', BD', CA'$ và $DB'$ của hình hộp cùng đi qua trung điểm của mỗi đường.",
    "**Giải**",
    "Đáy $ABCD$ của hình hộp là hình bình hành nên $AD // BC$ và $AD = BC$. Mặt bên $BCC'B'$ của hình hộp là hình bình hành nên $BC // B'C'$ và $BC = B'C'$. Vậy $AD // B'C'$ và $AD = B'C'$, suy ra tứ giác $ADC'B'$ là hình bình hành. Từ đó $AC'$ và $DB'$ cắt nhau tại trung điểm của mỗi đường. Tương tự $AC'$ và $BD', AC'$ và $CA'$ cũng cắt nhau tại trung điểm của mỗi đường. Vậy bốn đường chéo của hình hộp cùng đi qua trung điểm của mỗi đường.",
    "",
    "[Hình ảnh: Hình hộp ABCD.A'B'C'D'. Các đường chéo AC', BD', A'C, B'D cắt nhau tại một điểm ở tâm hình hộp.]",
    "*Hình 4.52*",
    "",
    "**Luyện tập 6.** Cho hình hộp $ABCD.A'B'C'D'$. Chứng minh rằng hai mặt phẳng $(ADD'A')$ và $(BCC'B')$ song song với nhau.",
    "",
    "**Nhận xét.** Từ Ví dụ 6 và Luyện tập 6, ta có:",
    "– Các đường chéo của hình hộp cùng đi qua trung điểm của mỗi đường;",
    "– Các mặt đối diện của hình hộp song song với nhau và có thể coi là hai đáy của hình hộp.",
    "",
    "**Vận dụng 2.** Để xác định mực nước trong một chiếc bể có dạng hình hộp, bác Hà đặt một thanh gỗ đủ dài vào trong bể sao cho một đầu của thanh gỗ dựa vào mép của nắp bể, đầu còn lại nằm trên đáy bể (H.4.53). Sau đó bác Hà rút thanh gỗ ra ngoài và tính tỉ lệ giữa độ dài của phần thanh gỗ bị ngâm trong nước và độ dài của cả thanh gỗ. Tỉ lệ này chính bằng tỉ lệ giữa mực nước và chiều cao của bể. Hãy giải thích vì sao.",
    "",
    "[Hình ảnh: Một người phụ nữ đang cắm một thanh gỗ vào một bể nước hình hộp để đo mực nước.]",
    "*Hình 4.53*",
    "",
    "# BÀI TẬP",
    "",
    "**4.21.** Trong không gian cho ba mặt phẳng phân biệt $(P), (Q), (R)$. Những mệnh đề nào sau đây là đúng?",
    "a) Nếu $(P)$ chứa một đường thẳng song song với $(Q)$ thì $(P)$ song song với $(Q)$.",
    "",
    "93",
    "b) Nếu $(P)$ chứa hai đường thẳng song song với $(Q)$ thì $(P)$ song song với $(Q)$.",
    "c) Nếu $(P)$ và $(Q)$ song song với $(R)$ thì $(P)$ song song với $(Q)$.",
    "d) Nếu $(P)$ và $(Q)$ cắt $(R)$ thì $(P)$ và $(Q)$ song song với nhau.",
    "",
    "**4.22.** Cho hình lăng trụ tam giác $ABC.A'B'C'$. Gọi $M, N, P$ lần lượt là trung điểm của các cạnh $AA', BB', CC'$. Chứng minh rằng mặt phẳng $(MNP)$ song song với mặt phẳng $(ABC)$.",
    "",
    "**4.23.** Cho hình thang $ABCD$ có hai đáy $AB$ và $CD$. Qua các điểm $A, D$ lần lượt vẽ các đường thẳng $m, n$ song song với nhau và không nằm trong mặt phẳng $(ABCD)$. Chứng minh rằng $\\text{mp}(B, m)$ và $\\text{mp}(C, n)$ song song với nhau.",
    "",
    "**4.24.** Cho hình tứ diện $SABC$. Trên cạnh $SA$ lấy các điểm $A_1, A_2$ sao cho $AA_1 = A_1A_2 = A_2S$. Gọi $(P)$ và $(Q)$ là hai mặt phẳng song song với mặt phẳng $(ABC)$ và lần lượt đi qua $A_1, A_2$. Mặt phẳng $(P)$ cắt các cạnh $SB, SC$ lần lượt tại $B_1, C_1$. Mặt phẳng $(Q)$ cắt các cạnh $SB, SC$ lần lượt tại $B_2, C_2$. Chứng minh $BB_1 = B_1B_2 = B_2S$ và $CC_1 = C_1C_2 = C_2S$.",
    "",
    "**4.25.** Cho hình lăng trụ tứ giác $ABCD.A'B'C'D'$. Một mặt phẳng song song với mặt phẳng $(A'B'C'D')$ cắt các cạnh bên của hình lăng trụ lần lượt tại $A'', B'', C'', D''$. Hỏi hình tạo bởi các điểm $A, B, C, D, A'', B'', C'', D''$ là hình gì?",
    "",
    "**4.26.** Cho hình lăng trụ tam giác $ABC.A'B'C'$. Gọi $G$ và $G'$ lần lượt là trọng tâm của hai tam giác $ABC$ và $A'B'C'$.",
    "a) Chứng minh rằng tứ giác $AGG'A'$ là hình bình hành.",
    "b) Chứng minh rằng $AGC.A'G'C'$ là hình lăng trụ.",
    "",
    "**4.27.** Cho hình hộp $ABCD.A'B'C'D'$. Một mặt phẳng song song với mặt bên $(ABB'A')$ của hình hộp và cắt các cạnh $AD, BC, A'D', B'C'$ lần lượt tại $M, N, M', N'$ (H.4.54). Chứng minh rằng $ABNM.A'B'N'M'$ là hình hộp.",
    "",
    "[Hình ảnh: Hình hộp ABCD.A'B'C'D'. Mặt phẳng (MNN'M') cắt hình hộp, song song với mặt (ABB'A'). M trên AD, N trên BC, M' trên A'D', N' trên B'C'.]",
    "*Hình 4.54*",
    "",
    "**4.28.** Cầu thang xương cá là dạng cầu thang có hình dáng tương tự như những đốt xương cá, thường có những bậc cầu thang với khoảng mở lớn, tạo được sự nhẹ nhàng và thoáng đãng cho không gian sống. Trong Hình 4.55, phần mép của mỗi bậc thang nằm trên tường song song với nhau. Hãy giải thích tại sao.",
    "",
    "[Hình ảnh: Cầu thang xương cá bằng gỗ với khung sắt.]",
    "*Hình 4.55*",
    "",
    "94"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN11_T1')), 'B14', 'Phép chiếu song song', 95, 5, $JSON$
{
  "content": [
    "# Bài 14. PHÉP CHIẾU SONG SONG",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Phép chiếu song song<br>• Hình chiếu<br>• Phương chiếu<br>• Hình biểu diễn | • Nhận biết khái niệm và tính chất cơ bản về phép chiếu song song.<br>• Xác định ảnh của một điểm, một đoạn thẳng, một tam giác, một đường tròn qua phép chiếu song song.<br>• Vẽ hình biểu diễn của một số hình khối đơn giản.<br>• Mô tả một số hình ảnh trong thực tiễn có liên quan đến phép chiếu song song. |",
    "",
    "Trong bóng đá, công nghệ Goal-line được sử dụng để xác định xem bóng đã hoàn toàn vượt qua vạch vôi hay chưa, từ đó giúp trọng tài đưa ra quyết định về một bàn thắng có được ghi hay không. Yếu tố hình học nào cho ta biết quả bóng đã vượt qua vạch vôi hay chưa?",
    "",
    "[Hình ảnh: Bóng đá nằm ngay sát vạch vôi cầu môn. Hình chiếu vuông góc của quả bóng xuống mặt sân không chạm vạch vôi, có nghĩa là bóng đã hoàn toàn vượt qua vạch vôi.]",
    "*Một bàn thắng được ghi.*",
    "",
    "## 1. PHÉP CHIẾU SONG SONG",
    "**HĐ1.** Một khung cửa sổ có dạng hình tròn với các chấn song tạo thành hình vuông $ABCD$, hai đường chéo của hình vuông cắt nhau tại $O$. Dưới ánh mặt trời, khung cửa và các chấn song đổ bóng lên sàn nhà (H.4.56a). Quan sát hình vẽ và trả lời các câu hỏi sau:",
    "a) Các đường thẳng nối mỗi điểm $A, B, C, D$ với bóng $A', B', C', D'$ có đôi một song song hay không?",
    "b) Làm thế nào để xác định được bóng đổ trên sàn nhà của mỗi điểm trên khung cửa sổ?",
    "",
    "[Hình ảnh: Hình 4.56a: Khung cửa sổ hình tròn với các chấn song tạo thành hình vuông ABCD đổ bóng xuống sàn nhà tạo thành hình elip và hình bình hành A'B'C'D'. Hình 4.56b: Đường thẳng Delta cắt mặt phẳng alpha. Các điểm M trên không gian chiếu xuống mặt phẳng alpha theo phương Delta tạo thành điểm M'.]",
    "*Hình 4.56*",
    "",
    "95",
    "| |",
    "| :--- |",
    "| Cho mặt phẳng $(\\alpha)$ và đường thẳng $\\Delta$ cắt $(\\alpha)$. Với mỗi điểm $M$ trong không gian ta xác định điểm $M'$ như sau:<br>• Nếu $M$ thuộc $\\Delta$ thì $M'$ là giao điểm của $(\\alpha)$ và $\\Delta$.<br>• Nếu $M$ không thuộc $\\Delta$ thì $M'$ là giao điểm của $(\\alpha)$ và đường thẳng qua $M$ song song với $\\Delta$.<br>Điểm $M'$ được gọi là hình chiếu song song của điểm $M$ trên mặt phẳng $(\\alpha)$ theo phương $\\Delta$.<br>Phép đặt tương ứng mỗi điểm $M$ với hình chiếu $M'$ của nó được gọi là **phép chiếu song song** lên $(\\alpha)$ theo phương $\\Delta$.<br>Mặt phẳng $(\\alpha)$ được gọi là mặt phẳng chiếu, phương $\\Delta$ được gọi là **phương chiếu**. |",
    "",
    "**?** Trong HĐ1, làm thế nào để xác định được bóng của toàn bộ song cửa $CD$ trên sàn nhà?",
    "",
    "| |",
    "| :--- |",
    "| Cho hình $\\mathscr{H}$. Tập hợp $\\mathscr{H}'$ các hình chiếu $M'$ của các điểm $M$ thuộc $\\mathscr{H}$ qua phép chiếu song song được gọi là **hình chiếu** của $\\mathscr{H}$ qua phép chiếu song song đó. |",
    "",
    "[Hình ảnh: Hình bên trái: Một khung hình chữ nhật và bóng của nó (là một hình bình hành) dưới phép chiếu song song. Hình bên phải: Bóng đổ của người bán hàng rong trên đường phố dưới ánh nắng mặt trời.]",
    "*Hình chiếu của hình chữ \"A\" | Bóng đổ của người bán hàng rong dưới ánh mặt trời trên đường phố Hội An*",
    "",
    "**Chú ý.** Nếu một đường thẳng cùng phương với phương chiếu thì hình chiếu của đường thẳng đó là một điểm. Kể từ đây, khi xét hình chiếu của đường thẳng, nếu không nói gì thêm ta chỉ xét hình chiếu của các đường thẳng không cùng phương với phương chiếu.",
    "",
    "**Ví dụ 1.** Cho hình lăng trụ tam giác $ABC.A'B'C'$.",
    "a) Xác định hình chiếu của điểm $A$ trên mặt phẳng $(A'B'C')$ theo phương $CC'$.",
    "b) Gọi $M$ là một điểm thuộc đoạn thẳng $AB$. Xác định hình chiếu của $M$ trên mặt phẳng $(A'B'C')$ theo phương $CC'$.",
    "**Giải** (H.4.57)",
    "a) Vì $ABC.A'B'C'$ là hình lăng trụ nên $AA' // BB' // CC'$. Vì $A'$ thuộc mặt phẳng $(A'B'C')$ nên $A'$ là hình chiếu của $A$ trên mặt phẳng $(A'B'C')$ theo phương $CC'$.",
    "b) Trong mặt phẳng $(ABB'A')$ vẽ $MM' // AA'$ với $M'$ thuộc $A'B'$ thì $MM' // CC'$. Vì $M'$ thuộc mặt phẳng $(A'B'C')$ nên $M'$ là hình chiếu của $M$ trên mặt phẳng $(A'B'C')$ theo phương $CC'$.",
    "",
    "[Hình ảnh: Hình lăng trụ tam giác ABC.A'B'C'. M thuộc AB, qua M kẻ MM' song song với AA' cắt A'B' tại M'.]",
    "*Hình 4.57*",
    "",
    "96",
    "**Luyện tập 1.** Cho hình hộp $ABCD.EFGH$ (H.4.58). Xác định hình chiếu của điểm $A$ trên mặt phẳng $(DCGH)$ theo phương $BC$ và theo phương $BG$.",
    "",
    "[Hình ảnh: Hình hộp ABCD.EFGH. Mặt đáy dưới là EFGH, mặt đáy trên là ABCD.]",
    "*Hình 4.58*",
    "",
    "**Vận dụng 1.** Trong *hình ảnh mở đầu*, khi một bàn thắng được ghi thì hình chiếu của quả bóng trên mặt đất theo phương thẳng đứng có vị trí như thế nào so với vạch vôi?",
    "",
    "## 2. TÍNH CHẤT CỦA PHÉP CHIẾU SONG SONG",
    "**HĐ2.** Quan sát Hình 4.56a và trả lời các câu hỏi sau:",
    "a) Hình chiếu $O'$ của điểm $O$ có nằm trên đoạn $A'C'$ hay không?",
    "b) Hình chiếu của hai song cửa $AB$ và $CD$ có song song với nhau không?",
    "c) Hình chiếu $O'$ của điểm $O$ có phải là trung điểm của đoạn $A'C'$ hay không?",
    "",
    "Ta có các tính chất sau của phép chiếu song song:",
    "",
    "| |",
    "| :--- |",
    "| • Phép chiếu song song biến ba điểm thẳng hàng thành ba điểm thẳng hàng và không làm thay đổi thứ tự ba điểm đó. Phép chiếu song song biến đường thẳng thành đường thẳng, tia thành tia, đoạn thẳng thành đoạn thẳng.<br>• Phép chiếu song song biến hai đường thẳng song song thành hai đường thẳng song song hoặc trùng nhau.<br>• Phép chiếu song song giữ nguyên tỉ số độ dài của hai đoạn thẳng cùng nằm trên một đường thẳng hoặc nằm trên hai đường thẳng song song. |",
    "",
    "[Hình ảnh: Hai hình minh hoạ tính chất của phép chiếu song song. Hình a: Phép chiếu song song giữ nguyên tỉ số đoạn thẳng trên hai đoạn thẳng song song: AB/CD = A'B'/C'D'. Hình b: Phép chiếu song song giữ nguyên tỉ số đoạn thẳng trên cùng một đường thẳng: AB/CD = A'B'/C'D'.]",
    "*Hình 4.59*",
    "",
    "**?** Hình chiếu của hai đường thẳng cắt nhau có phải là hai đường thẳng cắt nhau hay không?",
    "",
    "**Ví dụ 2.** Cho hình bình hành $ABCD$ và gọi $A'B'C'D'$ là hình chiếu của $ABCD$ trên mặt phẳng $(P)$ theo phương $d$ (H.4.60). Chứng minh rằng tứ giác $A'B'C'D'$ là hình bình hành.",
    "**Giải**",
    "Vì $ABCD$ là hình bình hành nên $AB$ song song với $CD$, do đó hình chiếu của $AB$ là $A'B'$ song song với hình chiếu của $CD$ là $C'D'$. Tương tự $A'D'$ song song với $B'C'$.",
    "Tứ giác $A'B'C'D'$ có $A'B' // C'D'$ và $A'D' // B'C'$ nên nó là hình bình hành.",
    "",
    "[Hình ảnh: Hình bình hành ABCD và hình chiếu A'B'C'D' của nó trên mặt phẳng P qua phép chiếu song song phương d. A'B'C'D' cũng là hình bình hành.]",
    "*Hình 4.60*",
    "",
    "97",
    "**Luyện tập 2.** Chứng minh rằng hình chiếu song song của một hình thang là một hình thang (H.4.61).",
    "",
    "[Hình ảnh: Hình thang ABCD (AB // CD) chiếu song song xuống mặt phẳng P theo phương d, tạo thành hình thang A'B'C'D'.]",
    "*Hình 4.61*",
    "",
    "**Ví dụ 3.** Cho tam giác $ABC$ có $M$ là trung điểm của $BC$. Một phép chiếu song song biến tam giác $ABC$ thành tam giác $A'B'C'$, biến $M$ thành $M'$. Chứng minh rằng $A'M'$ là đường trung tuyến của tam giác $A'B'C'$ (H.4.62).",
    "**Giải**",
    "Vì $M$ là trung điểm của $BC$ nên $B, M, C$ thẳng hàng theo thứ tự đó và $\\frac{BM}{MC} = 1$. Do vậy $B', M', C'$ thẳng hàng theo thứ tự đó và $\\frac{B'M'}{M'C'} = 1$, tức là $M'$ là trung điểm của $B'C'$. Vậy $A'M'$ là đường trung tuyến của tam giác $A'B'C'$.",
    "",
    "[Hình ảnh: Tam giác ABC và điểm M là trung điểm BC. Qua phép chiếu song song, tam giác ABC biến thành tam giác A'B'C' và M biến thành M'. A'M' là trung tuyến của tam giác A'B'C'.]",
    "*Hình 4.62*",
    "",
    "**Luyện tập 3.** Một phép chiếu song song biến tam giác $ABC$ thành tam giác $A'B'C'$. Chứng minh rằng phép chiếu đó biến đường trung bình của tam giác $ABC$ thành đường trung bình của tam giác $A'B'C'$.",
    "",
    "## 3. HÌNH BIỂU DIỄN CỦA MỘT HÌNH KHÔNG GIAN",
    "**HĐ3.** Trong ba hình dưới đây, hình nào thể hiện hình lập phương chính xác hơn?",
    "",
    "[Hình ảnh: Ba cách vẽ khối lập phương. Hình a) vẽ mặt trước là hình vuông, các cạnh xiên song song. Hình b) tương tự hình a nhưng chiều sâu ngắn hơn. Hình c) vẽ các cạnh song song nhưng có xu hướng hội tụ.]",
    "*Hình 4.63*",
    "",
    "Từ đầu chương, ta thường minh hoạ các hình tứ diện, hình lập phương, hình lăng trụ,... bằng các hình vẽ trên giấy. Các hình vẽ này đều tuân theo một nguyên tắc nhất định và chúng được gọi là hình biểu diễn của hình không gian trên mặt phẳng.",
    "",
    "| |",
    "| :--- |",
    "| **Hình biểu diễn** của một hình trong không gian là hình chiếu song song của hình đó trên một mặt phẳng theo một phương chiếu nào đó hoặc hình đồng dạng với hình chiếu đó. |",
    "",
    "**?** Quan sát hình ảnh khung cửa sổ trong Hình 4.56a và cho biết hình biểu diễn của hình tam giác, hình vuông, hình tròn là hình gì?",
    "",
    "98"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO chapters (textbook_id, code, name, sort_order) VALUES ((SELECT id FROM textbooks WHERE code = 'TOAN11_T1'), 'CH5', 'CHƯƠNG V. GIỚI HẠN. HÀM SỐ LIÊN TỤC', 5) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN11_T1')), 'B15', 'Giới hạn của dãy số', 104, 1, $JSON$
{
  "content": [
    "# CHƯƠNG V",
    "# GIỚI HẠN. HÀM SỐ LIÊN TỤC",
    "",
    "Chương này trình bày khái niệm giới hạn của dãy số, của hàm số và một số định lí, quy tắc tìm giới hạn. Chúng là cơ sở cho việc nghiên cứu các nội dung khác của Giải tích và cho phép giải quyết nhiều bài toán của khoa học và thực tiễn. Khái niệm hàm số liên tục và một vài tính chất đơn giản của chúng được trình bày ở phần cuối chương.",
    "",
    "[Hình ảnh: Biểu tượng vô cực được tạo thành từ nhiều chấm sáng nhỏ xếp theo hình số 8 nằm ngang màu xanh lục trên nền đen.]",
    "",
    "# Bài 15. GIỚI HẠN CỦA DÃY SỐ",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Giới hạn của dãy số<br>• Các phép toán giới hạn<br>• Cấp số nhân lùi vô hạn<br>• Tổng của cấp số nhân lùi vô hạn | • Nhận biết khái niệm giới hạn của dãy số.<br>• Giải thích một số giới hạn cơ bản.<br>• Vận dụng các phép toán giới hạn để tìm giới hạn của một số dãy số đơn giản.<br>• Tính tổng của một cấp số nhân lùi vô hạn và vận dụng được kết quả đó để giải quyết một số tình huống thực tiễn giả định hoặc liên quan đến thực tiễn. |",
    "",
    "**Nghịch lí Zeno.** Achilles (A-sin, một nhân vật trong thần thoại Hy Lạp, được mô tả là có thể chạy nhanh như gió) đuổi theo một con rùa trên một đường thẳng. Vị trí xuất phát của Achilles là $A_1$, cách vị trí xuất phát $R_1$ của rùa một quãng đường có chiều dài là $a$ (H.5.1). Zeno lí luận rằng, mặc dù chạy nhanh hơn nhưng Achilles không bao giờ đuổi kịp rùa.",
    "",
    "[Hình ảnh: Biểu diễn trên trục số. Các điểm A1, A2, A3, A4, A5, A6 biểu diễn vị trí của Achilles. Các điểm R1, R2, R3, R4, R5 biểu diễn vị trí của con rùa. R1 nằm cùng vị trí với A2. Khoảng cách giữa các điểm giảm dần theo thời gian.]",
    "*Hình 5.1*",
    "",
    "Thật vậy, trước tiên Achilles phải đến được vị trí $A_2 = R_1$ và trong khoảng thời gian này, rùa đã di chuyển đến vị trí $R_2$. Sau đó, Achilles phải đến được vị trí $A_3 = R_2$, lúc này rùa đã di chuyển đến vị trí $R_3$... Cứ như vậy, Achilles không bao giờ đuổi kịp rùa.",
    "",
    "Zeno (490 – 429 trước Công nguyên) là một triết gia Hy Lạp, đến từ thành phố Elea (miền nam nước Ý ngày nay). Trong số các nghịch lí của Zeno, nghịch lí Achilles đuổi rùa được coi là đã thúc đẩy sự hình thành khái niệm giới hạn, một công cụ thiết yếu của toán học, được sử dụng để nghiên cứu các quá trình liên quan đến sự vô hạn.",
    "",
    "104",
    ""
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN11_T1')), 'B16', 'Giới hạn của hàm số', 111, 2, $JSON$
{
  "content": [
    "# Bài 16. GIỚI HẠN CỦA HÀM SỐ",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Giới hạn của hàm số<br>• Giới hạn một phía<br>• Giới hạn tại vô cực<br>• Giới hạn vô cực | • Nhận biết khái niệm giới hạn hữu hạn của hàm số tại một điểm và tại vô cực.<br>• Nhận biết khái niệm giới hạn một phía.<br>• Nhận biết khái niệm giới hạn vô cực.<br>• Tính một số dạng giới hạn của hàm số.<br>• Giải quyết một số vấn đề thực tiễn gắn với giới hạn của hàm số. |",
    "",
    "Trong Thuyết tương đối của Einstein, khối lượng của vật chuyển động với vận tốc $v$ cho bởi công thức",
    "$m = \\frac{m_0}{\\sqrt{1 - \\frac{v^2}{c^2}}}$,",
    "trong đó $m_0$ là khối lượng của vật khi nó đứng yên, $c$ là vận tốc ánh sáng. Chuyện gì xảy ra với khối lượng của vật khi vận tốc của vật gần với vận tốc ánh sáng?",
    "",
    "[Hình ảnh: Chân dung Albert Einstein trên nền vũ trụ và một vật thể (như lỗ đen hoặc sao chổi) đang di chuyển với tốc độ cao.]",
    "*Albert Einstein (1879 – 1955)*",
    "",
    "## 1. GIỚI HẠN HỮU HẠN CỦA HÀM SỐ TẠI MỘT ĐIỂM",
    "",
    "**HĐ1.** Nhận biết khái niệm giới hạn tại một điểm",
    "Cho hàm số $f(x) = \\frac{4 - x^2}{x - 2}$.",
    "a) Tìm tập xác định của hàm số $f(x)$.",
    "b) Cho dãy số $x_n = 2 + \\frac{1}{n}$. Rút gọn $f(x_n)$ và tính giới hạn của dãy $(u_n)$ với $u_n = f(x_n)$.",
    "c) Với dãy số $(x_n)$ bất kì sao cho $x_n \\ne 2$ và $x_n \\to 2$, tính $f(x_n)$ và tìm $\\lim\\limits_{n \\to +\\infty} f(x_n)$.",
    "",
    "| |",
    "| :--- |",
    "| Giả sử $(a; b)$ là một khoảng chứa điểm $x_0$ và hàm số $y = f(x)$ xác định trên khoảng $(a; b)$, có thể trừ điểm $x_0$. Ta nói hàm số $f(x)$ **có giới hạn là số $L$ khi $x$ dần tới $x_0$** nếu với dãy số $(x_n)$ bất kì, $x_n \\in (a; b), x_n \\ne x_0$ và $x_n \\to x_0$, ta có $f(x_n) \\to L$, kí hiệu $\\lim\\limits_{x \\to x_0} f(x) = L$ hay $f(x) \\to L$ khi $x \\to x_0$. |",
    "",
    "**Ví dụ 1.** Cho hàm số $f(x) = \\frac{x - 1}{x^2 - 1}$. Chứng tỏ rằng $\\lim\\limits_{x \\to 1} f(x) = \\frac{1}{2}$.",
    "",
    "111",
    ""
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN11_T1')), 'B17', 'Hàm số liên tục', 119, 3, $JSON$
{
  "content": [
    "# Bài 17. HÀM SỐ LIÊN TỤC",
    "",
    "| THUẬT NGỮ | KIẾN THỨC, KĨ NĂNG |",
    "| :--- | :--- |",
    "| • Hàm số liên tục tại một điểm<br>• Hàm số gián đoạn<br>• Hàm số liên tục trên một khoảng<br>• Hàm số liên tục trên một đoạn | • Nhận dạng hàm số liên tục tại một điểm, hoặc trên một khoảng, trên một đoạn.<br>• Nhận dạng tính liên tục của tổng, hiệu, tích, thương của hai hàm số liên tục.<br>• Nhận biết tính liên tục của một số hàm sơ cấp cơ bản trên tập xác định của chúng. |",
    "",
    "Một người lái xe từ địa điểm $A$ đến địa điểm $B$ trong thời gian 3 giờ. Biết quãng đường từ $A$ đến $B$ dài $180 \\text{ km}$. Chứng tỏ rằng có ít nhất một thời điểm trên hành trình, xe chạy với vận tốc $60 \\text{ km/h}$.",
    "",
    "[Hình ảnh: Một chiếc ô tô đang chạy trên đường. Có một chú thích: Vận tốc = Quãng đường / Thời gian.]",
    "",
    "## 1. HÀM SỐ LIÊN TỤC TẠI MỘT ĐIỂM",
    "**HĐ1.** Nhận biết tính liên tục của hàm số tại một điểm",
    "Cho hàm số $f(x) = \\begin{cases} \\frac{x^2 - 1}{x - 1} & \\text{nếu } x \\ne 1 \\\\ 2 & \\text{nếu } x = 1 \\end{cases}$.",
    "Tính giới hạn $\\lim\\limits_{x \\to 1} f(x)$ và so sánh giá trị này với $f(1)$.",
    "",
    "| |",
    "| :--- |",
    "| Cho hàm số $y = f(x)$ xác định trên khoảng $(a; b)$ chứa điểm $x_0$. Hàm số $f(x)$ được gọi là **liên tục tại điểm $x_0$** nếu $\\lim\\limits_{x \\to x_0} f(x) = f(x_0)$. |",
    "",
    "Hàm số $f(x)$ không liên tục tại $x_0$ được gọi là **gián đoạn** tại điểm đó.",
    "",
    "**Ví dụ 1.** Xét tính liên tục của hàm số $f(x) = \\frac{x + 1}{x - 1}$ tại điểm $x_0 = 2$.",
    "**Giải**",
    "Rõ ràng hàm số $f(x)$ xác định trên $\\mathbb{R} \\setminus \\{1\\}$, do đó $x_0 = 2$ thuộc tập xác định của hàm số.",
    "Ta có $\\lim\\limits_{x \\to 2} f(x) = \\lim\\limits_{x \\to 2} \\frac{x + 1}{x - 1} = 3 = f(2)$. Vậy hàm số $f(x)$ liên tục tại $x_0 = 2$.",
    "",
    "119",
    ""
  ]
}
$JSON$) ON CONFLICT DO NOTHING;
